-- =============================================
-- Check Abbreviation Uniqueness
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_CheckAbbreviationUnique]
    @Abbreviation NVARCHAR(20),
    @Id INT = NULL,
    @CompanyId INT,
    @IsUnique BIT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;
    
    IF EXISTS (
        SELECT 1 
        FROM PARTY_MASTER 
        WHERE P_ABBREVATION = @Abbreviation 
          AND P_CM_COMP_ID = @CompanyId 
          AND P_TYPE = 1
          AND (@Id IS NULL OR P_CODE <> @Id)
    )
        SET @IsUnique = 0;
    ELSE
        SET @IsUnique = 1;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_CheckCustomerPoLock]
    @PoCode INT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        SELECT ISNULL(MODIFY, 0) AS IsLocked
        FROM CUSTPO_MASTER
        WHERE CPOM_CODE = @PoCode;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_CheckCustomerTypeUsage]
    @CTM_CODE INT,
    @IsUsed BIT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    DECLARE @Count INT;

    -- Check if customer type is used in PARTY_MASTER (P_TYPE=1 indicates customer)
    SELECT @Count = COUNT(*)
    FROM PARTY_MASTER
    WHERE P_CUST_TYPE = @CTM_CODE
        AND P_TYPE = 1
        AND ES_DELETE = 0;

    IF @Count > 0
        SET @IsUsed = 1;
    ELSE
        SET @IsUsed = 0;
END;
GO

-- =============================================
-- Stored Procedure: ERP_CheckCustomerUsage
-- Description: Checks if a Customer Master record is used in any transactions
-- Returns: 1 if used, 0 if not used
-- Note: This checks common transaction tables (SO_MASTER, INVOICE_MASTER, etc.)
-- =============================================
CREATE OR ALTER PROCEDURE ERP_CheckCustomerUsage
    @Id INT
AS
BEGIN
    SET NOCOUNT OFF;

    DECLARE @Count INT = 0;

    -- Check if used in SO_MASTER (Sales Order)
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'SO_MASTER')
    BEGIN
        EXEC sp_executesql N'SELECT @Count = @Count + COUNT(*) FROM SO_MASTER WHERE SO_P_CODE = @Id', 
            N'@Id INT, @Count INT OUTPUT', @Id, @Count OUTPUT;
    END

    -- Check if used in INVOICE_MASTER (Invoice)
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'INVOICE_MASTER')
    BEGIN
        EXEC sp_executesql N'SELECT @Count = @Count + COUNT(*) FROM INVOICE_MASTER WHERE INV_P_CODE = @Id', 
            N'@Id INT, @Count INT OUTPUT', @Id, @Count OUTPUT;
    END

    -- Check if used in CHALLAN_MASTER (Delivery Challan)
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'CHALLAN_MASTER')
    BEGIN
        EXEC sp_executesql N'SELECT @Count = @Count + COUNT(*) FROM CHALLAN_MASTER WHERE CH_P_CODE = @Id', 
            N'@Id INT, @Count INT OUTPUT', @Id, @Count OUTPUT;
    END

    -- Check if used in QUOTATION_MASTER (Quotation)
    IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = 'QUOTATION_MASTER')
    BEGIN
        EXEC sp_executesql N'SELECT @Count = @Count + COUNT(*) FROM QUOTATION_MASTER WHERE Q_P_CODE = @Id', 
            N'@Id INT, @Count INT OUTPUT', @Id, @Count OUTPUT;
    END

    IF @Count > 0
        SELECT 1 AS IsUsed; -- Used in transactions
    ELSE
        SELECT 0 AS IsUsed; -- Not used
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-10-24
-- Description: Checks if an invoice is locked for editing
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_CheckInvoiceLock]
    @InvoiceCode INT,
    @IsLocked BIT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        SELECT @IsLocked = ISNULL(MODIFY, 0) 
        FROM INVOICE_MASTER 
        WHERE INM_CODE = @InvoiceCode;

        -- If invoice not found, return 0 (not locked)
        IF @IsLocked IS NULL
            SET @IsLocked = 0;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

