-- =============================================
-- Create Customer Master
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_CreateCustomerMaster]
    @CompanyId INT,
    @PartyName NVARCHAR(500),
    @ContactPerson NVARCHAR(75) = NULL,
    @Abbreviation NVARCHAR(20) = NULL,
    @VendorCode NVARCHAR(30) = NULL,
    @Address NVARCHAR(255) = NULL,
    @Phone NVARCHAR(50) = NULL,
    @Mobile NVARCHAR(55) = NULL,
    @Email NVARCHAR(100) = NULL,
    @FaxNo NVARCHAR(50) = NULL,
    @PinCode NVARCHAR(15) = NULL,
    @AreaCode INT,
    @CustomerType VARCHAR(20),
    @CountryCode INT = NULL,
    @StateCode INT = NULL,
    @CityCode INT = NULL,
    @CategoryCode INT = NULL,
    @EmployeeCode INT = NULL,
    @PanNo NVARCHAR(25) = NULL,
    @CstNo NVARCHAR(50) = NULL,
    @VatNo NVARCHAR(50) = NULL,
    @ServiceTaxNo NVARCHAR(50) = NULL,
    @EccNo NVARCHAR(50) = NULL,
    @LbtNo NVARCHAR(50) = NULL,
    @ExciseRange NVARCHAR(50) = NULL,
    @ExciseDivision NVARCHAR(50) = NULL,
    @ExciseCollectorate NVARCHAR(50) = NULL,
    @TallyName NVARCHAR(MAX) = NULL,
    @CreditDays INT = NULL,
    @TdsPercentage FLOAT = NULL,
    @IsActive BIT = 1,
    @IsLbtApplicable BIT = 0,
    @NewId INT OUTPUT,
    @NewPartyCode INT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;
    
    BEGIN TRY
        BEGIN TRANSACTION;
        
        -- Generate new P_PARTY_CODE
        DECLARE @MaxPartyCode INT;
        SELECT @MaxPartyCode = ISNULL(MAX(P_PARTY_CODE), 0) + 1
        FROM PARTY_MASTER
        WHERE P_CM_COMP_ID = @CompanyId;
        
        SET @NewPartyCode = @MaxPartyCode;
        
        -- Insert new customer (use ISNULL for non-nullable columns)
        INSERT INTO PARTY_MASTER (
            P_CM_COMP_ID, P_PARTY_CODE, P_TYPE, P_NAME, P_CONTACT, 
            P_ABBREVATION, P_VEND_CODE, P_ADD1, P_PHONE, P_MOB, 
            P_EMAIL, P_FAX, P_PIN_CODE, P_A_CODE, P_CUST_TYPE, 
            P_COUNTRY_CODE, P_SM_CODE, P_CITY_CODE, P_CATEGORY, P_E_CODE,
            P_PAN, P_CST, P_VAT, P_SER_TAX_NO, P_ECC_NO, P_LBT_NO,
            P_EXC_RANGE, P_EXC_DIV, P_EXC_COLLECTORATE, P_TALLY,
            P_CREDITDAYS, P_TDS, P_ACTIVE_IND, P_LBT_IND
        )
        VALUES (
            @CompanyId, @NewPartyCode, 1, @PartyName, ISNULL(@ContactPerson, ''),
            ISNULL(@Abbreviation, ''), @VendorCode, ISNULL(@Address, ''), @Phone, @Mobile,
            @Email, @FaxNo, @PinCode, @AreaCode, @CustomerType,
            @CountryCode, @StateCode, @CityCode, @CategoryCode, @EmployeeCode,
            @PanNo, @CstNo, @VatNo, @ServiceTaxNo, @EccNo, @LbtNo,
            @ExciseRange, @ExciseDivision, @ExciseCollectorate, @TallyName,
            @CreditDays, @TdsPercentage, @IsActive, @IsLbtApplicable
        );
        
        SET @NewId = SCOPE_IDENTITY();
        
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_CreateCustomerPo]
    @CustomerCode INT,
    @PoNumber VARCHAR(100),
    @PoType INT,
    @PoDate DATETIME,
    @CreditDays INT,
    @CompanyId INT,
    @WorkOrderNumber VARCHAR(50) = NULL,
    @PaymentTerms VARCHAR(260) = NULL,
    @IsAuthorized BIT = 0,
    @CustomerPoDate DATETIME = NULL,
    @QuotationCode INT = NULL,
    @TaxName VARCHAR(50) = NULL,
    @TaxPercentage FLOAT = NULL,
    @TaxAmount FLOAT = NULL,
    @ExcisePercentage FLOAT = NULL,
    @ExciseEducationPercentage FLOAT = NULL,
    @ExciseHigherEducationPercentage FLOAT = NULL,
    @BasicAmount FLOAT = NULL,
    @DiscountPercentage FLOAT = NULL,
    @DiscountAmount FLOAT = NULL,
    @DiscountReason VARCHAR(50) = NULL,
    @DeviationAmount FLOAT = NULL,
    @DeviationReason VARCHAR(50) = NULL,
    @PackingAmount FLOAT = NULL,
    @ExciseAmount FLOAT = NULL,
    @RoundingAmount FLOAT = NULL,
    @GrandTotal FLOAT = NULL,
    @FinalDestination VARCHAR(50) = NULL,
    @PreCarriageBy VARCHAR(50) = NULL,
    @PortOfLoading VARCHAR(50) = NULL,
    @PortOfDischarge VARCHAR(50) = NULL,
    @PlaceOfDelivery VARCHAR(50) = NULL,
    @BuyerName VARCHAR(50) = NULL,
    @BuyerAddress VARCHAR(150) = NULL,
    @CurrencyCode INT = NULL,
    @InquiryCode INT = NULL,
    @IsVerbalOrder BIT = 0,
    @ProjectCode INT = NULL,
    @ProjectName VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @NewPoCode INT;

        -- Get next document number
        DECLARE @DocNumber INT;
        SELECT @DocNumber = ISNULL(MAX(CPOM_DOC_NO), 0) + 1 
        FROM CUSTPO_MASTER 
        WHERE CPOM_CM_COMP_ID = @CompanyId;

        -- Insert master record
        INSERT INTO CUSTPO_MASTER (
            CPOM_P_CODE,
            CPOM_PONO,
            CPOM_DOC_NO,
            CPOM_TYPE,
            CPOM_DATE,
            CPOM_CR_DAYS,
            CPOM_CM_COMP_ID,
            CPOM_WORK_ODR_NO,
            CPOM_PAY_TERM,
            CPOM_AUTH_FLG,
            CPOM_PO_DATE,
            CPOM_QE_CODE,
            CPOM_T_NAME,
            CPOM_T_PER,
            CPOM_T_AMT,
            CPOM_EXC_PER,
            CPOM_EXC_EDU_PER,
            CPOM_EXC_HEDU_PER,
            CPOM_BASIC_AMT,
            CPOM_DISCOUNT_PER,
            CPOM_DISCOUNT_AMT,
            CPOM_DISCOUNT_REASON,
            CPOM_DEVIATION_AMT,
            CPOM_DEVIATION_REASON,
            CPOM_PACKING_AMT,
            CPOM_EXC_AMT,
            CPOM_ROUNDING,
            CPOM_GRAND_TOT,
            CPOM_INV_FLAG,
            CPOM_AM_COUNT,
            CPOM_FINAL_DEST,
            CPOM_PRE_CARR_BY,
            CPOM_PORT_LOAD,
            CPOM_PORT_DIS,
            CPOM_PLACE_DEL,
            CPOM_BUYER_NAME,
            CPOM_BUYER_ADD,
            CPOM_CURR_CODE,
            CPOM_INQ_CODE,
            CPOM_IS_VERBAL,
            CPOM_PROJECT_CODE,
            CPOM_PROJECT_NAME,
            MODIFY,
            ES_DELETE
        )
        VALUES (
            @CustomerCode,
            @PoNumber,
            @DocNumber,
            @PoType,
            @PoDate,
            @CreditDays,
            @CompanyId,
            @WorkOrderNumber,
            @PaymentTerms,
            @IsAuthorized,
            @CustomerPoDate,
            @QuotationCode,
            @TaxName,
            @TaxPercentage,
            @TaxAmount,
            @ExcisePercentage,
            @ExciseEducationPercentage,
            @ExciseHigherEducationPercentage,
            @BasicAmount,
            @DiscountPercentage,
            @DiscountAmount,
            @DiscountReason,
            @DeviationAmount,
            @DeviationReason,
            @PackingAmount,
            @ExciseAmount,
            @RoundingAmount,
            @GrandTotal,
            0, -- INV_FLAG
            0, -- AM_COUNT
            @FinalDestination,
            @PreCarriageBy,
            @PortOfLoading,
            @PortOfDischarge,
            @PlaceOfDelivery,
            @BuyerName,
            @BuyerAddress,
            @CurrencyCode,
            @InquiryCode,
            @IsVerbalOrder,
            @ProjectCode,
            @ProjectName,
            0, -- MODIFY
            0  -- ES_DELETE
        );

        SET @NewPoCode = SCOPE_IDENTITY();
        
        -- Auto-generate Work Order Number if not provided (based on Document Number, matching legacy behavior)
        IF @WorkOrderNumber IS NULL OR @WorkOrderNumber = ''
        BEGIN
            SET @WorkOrderNumber = 'WO' + CAST(@DocNumber AS VARCHAR(50));
            
            -- Update the record with the generated Work Order Number
            UPDATE CUSTPO_MASTER
            SET CPOM_WORK_ODR_NO = @WorkOrderNumber
            WHERE CPOM_CODE = @NewPoCode;
        END
        
        SELECT @NewPoCode AS PoCode;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

