-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Soft deletes a Tax Invoice (sets ES_DELETE = 1) and reverses stock
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_DeleteTaxInvoice]
    @InvoiceCode INT,
    @CompanyCode INT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        -- Reverse stock (delete all stock ledger entries for this invoice)
        DELETE FROM STOCK_LEDGER
        WHERE STL_DOC_NO = @InvoiceCode 
        AND STL_DOC_TYPE = 'TAXINV';
        
        -- Soft delete invoice details
        UPDATE INVOICE_DETAIL
        SET ES_DELETE = 1
        WHERE IND_INM_CODE = @InvoiceCode;

        -- Soft delete invoice master
        UPDATE INVOICE_MASTER
        SET ES_DELETE = 1
        WHERE INM_CODE = @InvoiceCode AND INM_CM_CODE = @CompanyCode;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Generates next Invoice Number for a company
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GenerateInvoiceNumber]
    @CompanyCode INT,
    @NewInvoiceNumber INT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        -- Get the max invoice number for this company and increment
        SELECT @NewInvoiceNumber = ISNULL(MAX(INM_NO), 0) + 1
        FROM INVOICE_MASTER
        WHERE INM_CM_CODE = @CompanyCode;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetActiveCompanies]
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Query matches legacy: select distinct CM_ID,CM_NAME from COMPANY_MASTER where CM_ACTIVE_IND=1
    SELECT DISTINCT 
        CM_ID AS Id,
        CM_NAME AS DisplayName
    FROM COMPANY_MASTER 
    WHERE CM_ACTIVE_IND = 1 
    ORDER BY CM_NAME;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetAllCustomerPos]
    @CompanyId INT,
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @IsActive BIT = 1,
    @SearchTerm NVARCHAR(100) = NULL,
    @PoNumber VARCHAR(100) = NULL,
    @CustomerCode INT = NULL,
    @CustomerName NVARCHAR(100) = NULL,
    @FromDate DATETIME = NULL,
    @ToDate DATETIME = NULL,
    @WorkOrderNumber VARCHAR(50) = NULL,
    @CustomerItemCode NVARCHAR(100) = NULL,
    @PoType INT = NULL,
    @ProjectCode INT = NULL,
    @InvoiceGenerated BIT = NULL,
    @HasAmendment BIT = NULL,
    @IsVerbalOrder BIT = NULL,
    @SortBy NVARCHAR(50) = 'PoCode',
    @SortOrder NVARCHAR(4) = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

        -- Build WHERE clause conditions
        DECLARE @SQL NVARCHAR(MAX);
        DECLARE @CountSQL NVARCHAR(MAX);
        DECLARE @WHERE NVARCHAR(MAX) = ' WHERE m.CPOM_CM_COMP_ID = @CompanyId ';

        IF @IsActive = 1
            SET @WHERE = @WHERE + ' AND m.ES_DELETE = 0 ';
        ELSE
            SET @WHERE = @WHERE + ' AND m.ES_DELETE = 1 ';

        IF @SearchTerm IS NOT NULL AND @SearchTerm != ''
            SET @WHERE = @WHERE + ' AND (m.CPOM_PONO LIKE ''%'' + @SearchTerm + ''%'' 
                OR p.P_NAME LIKE ''%'' + @SearchTerm + ''%'' 
                OR m.CPOM_WORK_ODR_NO LIKE ''%'' + @SearchTerm + ''%'') ';

        IF @PoNumber IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_PONO LIKE ''%'' + @PoNumber + ''%'' ';

        IF @CustomerCode IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_P_CODE = @CustomerCode ';

        IF @CustomerName IS NOT NULL
            SET @WHERE = @WHERE + ' AND p.P_NAME LIKE ''%'' + @CustomerName + ''%'' ';

        IF @FromDate IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_DATE >= @FromDate ';

        IF @ToDate IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_DATE <= @ToDate ';

        IF @WorkOrderNumber IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_WORK_ODR_NO LIKE ''%'' + @WorkOrderNumber + ''%'' ';

        IF @CustomerItemCode IS NOT NULL
            SET @WHERE = @WHERE + ' AND EXISTS (SELECT 1 FROM CUSTPO_DETAIL d WHERE d.CPOD_CPOM_CODE = m.CPOM_CODE AND d.CPOD_CUST_I_CODE LIKE ''%'' + @CustomerItemCode + ''%'') ';

        IF @PoType IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_TYPE = @PoType ';

        IF @ProjectCode IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_PROJECT_CODE = @ProjectCode ';

        IF @InvoiceGenerated IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_INV_FLAG = @InvoiceGenerated ';

        IF @HasAmendment IS NOT NULL
        BEGIN
            IF @HasAmendment = 1
                SET @WHERE = @WHERE + ' AND m.CPOM_AM_COUNT > 0 ';
            ELSE
                SET @WHERE = @WHERE + ' AND m.CPOM_AM_COUNT = 0 ';
        END

        IF @IsVerbalOrder IS NOT NULL
            SET @WHERE = @WHERE + ' AND m.CPOM_IS_VERBAL = @IsVerbalOrder ';

        -- Build ORDER BY clause
        DECLARE @ORDERBY NVARCHAR(200) = ' ORDER BY ';
        IF @SortBy = 'PoCode'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_CODE ';
        ELSE IF @SortBy = 'PoNumber'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_PONO ';
        ELSE IF @SortBy = 'PoDate'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_DATE ';
        ELSE IF @SortBy = 'CustomerName'
            SET @ORDERBY = @ORDERBY + 'p.P_NAME ';
        ELSE IF @SortBy = 'GrandTotal'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_GRAND_TOT ';
        ELSE IF @SortBy = 'WorkOrderNumber'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_WORK_ODR_NO ';
        ELSE IF @SortBy = 'AmendmentCount'
            SET @ORDERBY = @ORDERBY + 'm.CPOM_AM_COUNT ';
        ELSE IF @SortBy = 'CustomerPartNo'
            -- Sort by first detail's customer item code using subquery
            SET @ORDERBY = @ORDERBY + '(SELECT TOP 1 d.CPOD_CUST_I_CODE FROM CUSTPO_DETAIL d WHERE d.CPOD_CPOM_CODE = m.CPOM_CODE ORDER BY d.CPOD_CPOM_CODE) ';
        ELSE
            SET @ORDERBY = @ORDERBY + 'm.CPOM_CODE ';

        SET @ORDERBY = @ORDERBY + @SortOrder;

        -- Get paginated data
        SET @SQL = N'
        SELECT 
            m.CPOM_CODE AS PoCode,
            m.CPOM_P_CODE AS CustomerCode,
            p.P_NAME AS CustomerName,
            m.CPOM_PONO AS PoNumber,
            m.CPOM_DOC_NO AS DocumentNumber,
            m.CPOM_TYPE AS PoType,
            m.CPOM_DATE AS PoDate,
            m.CPOM_CR_DAYS AS CreditDays,
            m.CPOM_CM_COMP_ID AS CompanyId,
            m.CPOM_WORK_ODR_NO AS WorkOrderNumber,
            m.MODIFY AS IsLocked,
            m.ES_DELETE AS IsDeleted,
            m.CPOM_GRAND_TOT AS GrandTotal,
            m.CPOM_INV_FLAG AS InvoiceGenerated,
            m.CPOM_AM_COUNT AS AmendmentCount,
            m.CPOM_IS_VERBAL AS IsVerbalOrder,
            m.CPOM_PROJECT_CODE AS ProjectCode,
            m.CPOM_PROJECT_NAME AS ProjectName
        FROM CUSTPO_MASTER m
        INNER JOIN PARTY_MASTER p ON m.CPOM_P_CODE = p.P_CODE ' + @WHERE + @ORDERBY + '
        OFFSET @Offset ROWS
        FETCH NEXT @PageSize ROWS ONLY;';

        -- Get total count
        SET @CountSQL = N'
        SELECT COUNT(*)
        FROM CUSTPO_MASTER m
        INNER JOIN PARTY_MASTER p ON m.CPOM_P_CODE = p.P_CODE ' + @WHERE;

        -- Execute data query
        EXEC sp_executesql @SQL, 
            N'@CompanyId INT, @Offset INT, @PageSize INT, @SearchTerm NVARCHAR(100), 
              @PoNumber VARCHAR(100), @CustomerCode INT, @CustomerName NVARCHAR(100), 
              @FromDate DATETIME, @ToDate DATETIME, @WorkOrderNumber VARCHAR(50), 
              @CustomerItemCode NVARCHAR(100), @PoType INT, @ProjectCode INT, 
              @InvoiceGenerated BIT, @IsVerbalOrder BIT',
            @CompanyId, @Offset, @PageSize, @SearchTerm, 
            @PoNumber, @CustomerCode, @CustomerName, 
            @FromDate, @ToDate, @WorkOrderNumber, 
            @CustomerItemCode, @PoType, @ProjectCode, 
            @InvoiceGenerated, @IsVerbalOrder;

        -- Execute count query
        EXEC sp_executesql @CountSQL, 
            N'@CompanyId INT, @SearchTerm NVARCHAR(100), 
              @PoNumber VARCHAR(100), @CustomerCode INT, @CustomerName NVARCHAR(100), 
              @FromDate DATETIME, @ToDate DATETIME, @WorkOrderNumber VARCHAR(50), 
              @CustomerItemCode NVARCHAR(100), @PoType INT, @ProjectCode INT, 
              @InvoiceGenerated BIT, @IsVerbalOrder BIT',
            @CompanyId, @SearchTerm, 
            @PoNumber, @CustomerCode, @CustomerName, 
            @FromDate, @ToDate, @WorkOrderNumber, 
            @CustomerItemCode, @PoType, @ProjectCode, 
            @InvoiceGenerated, @IsVerbalOrder;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Gets all Tax Invoices with filtering, searching, sorting, and pagination
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetAllTaxInvoices]
    @CompanyId INT,
    @CustomerId INT = NULL,
    @CustomerPoCode INT = NULL,
    @InvoiceDateFrom DATETIME = NULL,
    @InvoiceDateTo DATETIME = NULL,
    @InvoiceNumber VARCHAR(50) = NULL,
    @InvoiceType TINYINT = NULL,
    @IsDeleted BIT = NULL,
    @IsSupplementary BIT = NULL,
    @ExportFlag BIT = NULL,
    @SearchTerm NVARCHAR(200) = NULL,
    @SortBy NVARCHAR(50) = 'InvoiceDate',
    @SortOrder NVARCHAR(10) = 'desc',
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @TotalCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Build dynamic WHERE clause
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @CountSQL NVARCHAR(MAX);
    DECLARE @WhereClause NVARCHAR(MAX) = 'WHERE I.INM_CM_CODE = @CompanyId';

    IF @CustomerId IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_P_CODE = @CustomerId';

    -- Note: CustomerPoCode filter removed as PO is linked at detail level, not header level
    -- IF @CustomerPoCode IS NOT NULL
    --     SET @WhereClause = @WhereClause + ' AND I.INM_CPOM_CODE = @CustomerPoCode';

    IF @InvoiceDateFrom IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_DATE >= @InvoiceDateFrom';

    IF @InvoiceDateTo IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_DATE <= @InvoiceDateTo';

    IF @InvoiceNumber IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND CAST(I.INM_NO AS VARCHAR) LIKE ''%'' + @InvoiceNumber + ''%''';

    IF @InvoiceType IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_INVOICE_TYPE = @InvoiceType';

    IF @IsDeleted IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.ES_DELETE = @IsDeleted';
    ELSE
        SET @WhereClause = @WhereClause + ' AND I.ES_DELETE = 0'; -- Default: exclude deleted

    IF @IsSupplementary IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_SUPPLEMENTORY = @IsSupplementary';

    IF @ExportFlag IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND I.INM_EXPORT_FLAG = @ExportFlag';

    IF @SearchTerm IS NOT NULL AND @SearchTerm != ''
        SET @WhereClause = @WhereClause + ' AND (CAST(I.INM_NO AS VARCHAR) LIKE ''%'' + @SearchTerm + ''%'' OR P.P_NAME LIKE ''%'' + @SearchTerm + ''%'')';

    -- Build ORDER BY clause
    DECLARE @OrderByClause NVARCHAR(200) = 'ORDER BY ';
    IF @SortBy = 'InvoiceDate'
        SET @OrderByClause = @OrderByClause + 'I.INM_DATE';
    ELSE IF @SortBy = 'InvoiceNumber'
        SET @OrderByClause = @OrderByClause + 'I.INM_NO';
    ELSE IF @SortBy = 'CustomerName'
        SET @OrderByClause = @OrderByClause + 'P.P_NAME';
    ELSE IF @SortBy = 'GrossAmount'
        SET @OrderByClause = @OrderByClause + 'I.INM_G_AMT';
    ELSE
        SET @OrderByClause = @OrderByClause + 'I.INM_DATE';

    IF UPPER(@SortOrder) = 'DESC'
        SET @OrderByClause = @OrderByClause + ' DESC';
    ELSE
        SET @OrderByClause = @OrderByClause + ' ASC';

    -- Get total count
    SET @CountSQL = '
        SELECT @TotalCount = COUNT(*)
        FROM INVOICE_MASTER I
        LEFT JOIN PARTY_MASTER P ON I.INM_P_CODE = P.P_CODE
        ' + @WhereClause;

    EXEC sp_executesql @CountSQL, 
        N'@CompanyId INT, @CustomerId INT, @InvoiceDateFrom DATETIME, 
          @InvoiceDateTo DATETIME, @InvoiceNumber VARCHAR(50), @InvoiceType TINYINT, 
          @IsDeleted BIT, @IsSupplementary BIT, @ExportFlag BIT, @SearchTerm NVARCHAR(200), @TotalCount INT OUTPUT',
        @CompanyId, @CustomerId, @InvoiceDateFrom, @InvoiceDateTo, 
        @InvoiceNumber, @InvoiceType, @IsDeleted, @IsSupplementary, @ExportFlag, @SearchTerm, @TotalCount OUTPUT;

    -- Get paged data
    SET @SQL = '
        SELECT 
            I.INM_CODE AS InvoiceCode,
            I.INM_CM_CODE AS CompanyCode,
            I.INM_NO AS InvoiceNumber,
            I.INM_DATE AS InvoiceDate,
            I.INM_INVOICE_TYPE AS InvoiceType,
            I.INM_TYPE AS Type,
            I.INM_P_CODE AS CustomerCode,
            P.P_NAME AS CustomerName,
            I.INM_NET_AMT AS NetAmount,
            I.INM_TAXABLE_AMT AS TaxableAmount,
            I.INM_G_AMT AS GrossAmount,
            I.INM_BEXCISE AS BasicExcisePercentage,
            I.INM_BE_AMT AS BasicExciseAmount,
            I.INM_EDUC_CESS AS EducationCessPercentage,
            I.INM_EDUC_AMT AS EducationCessAmount,
            I.INM_H_EDUC_CESS AS HigherEducationCessPercentage,
            I.INM_H_EDUC_AMT AS HigherEducationCessAmount,
            I.INM_SUPPLEMENTORY AS IsSupplementary,
            I.INM_EXPORT_FLAG AS ExportFlag,
            I.INM_VEH_NO AS VehicleNumber,
            I.INM_TRANSPORT AS TransportName,
            I.INM_REMARK AS Remarks,
            I.ES_DELETE AS IsDeleted,
            I.MODIFY AS IsModifyLocked
        FROM INVOICE_MASTER I
        LEFT JOIN PARTY_MASTER P ON I.INM_P_CODE = P.P_CODE
        ' + @WhereClause + '
        ' + @OrderByClause + '
        OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY';

    EXEC sp_executesql @SQL, 
        N'@CompanyId INT, @CustomerId INT, @InvoiceDateFrom DATETIME, 
          @InvoiceDateTo DATETIME, @InvoiceNumber VARCHAR(50), @InvoiceType TINYINT, 
          @IsDeleted BIT, @IsSupplementary BIT, @ExportFlag BIT, @SearchTerm NVARCHAR(200), 
          @Offset INT, @PageSize INT',
        @CompanyId, @CustomerId, @InvoiceDateFrom, @InvoiceDateTo, 
        @InvoiceNumber, @InvoiceType, @IsDeleted, @IsSupplementary, @ExportFlag, @SearchTerm, 
        @Offset, @PageSize;

END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Gets available items from a Customer PO for invoicing
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetAvailableItemsFromPo]
    @CustomerPoCode INT,
    @CompanyCode INT
AS
BEGIN
    SET NOCOUNT OFF;

    -- Get items from Customer PO with remaining quantity to invoice
    SELECT 
        NULL AS InvoiceMasterCode,
        POD.CPODT_I_CODE AS ItemCode,
        I.I_CODENO AS ItemCode_Display,
        I.I_NAME AS ItemName,
        POD.CPODT_UOM_CODE AS UomCode,
        @CustomerPoCode AS CustomerPoCode,
        POD.CPODT_QTY AS InvoiceQuantity,
        POD.CPODT_RATE AS Rate,
        I.I_QTY AS StockQuantity,
        (POD.CPODT_QTY - ISNULL((
            SELECT SUM(IND_INQTY) 
            FROM INVOICE_DETAIL 
            WHERE IND_CPOM_CODE = @CustomerPoCode 
            AND IND_I_CODE = POD.CPODT_I_CODE
            AND ES_DELETE = 0
        ), 0)) AS PendingQuantity
    FROM CUSTOMER_PO_DETAIL POD
    INNER JOIN ITEM_MASTER I ON POD.CPODT_I_CODE = I.I_CODE
    INNER JOIN CUSTOMER_PO_MASTER POM ON POD.CPODT_CPOM_CODE = POM.CPOM_CODE
    WHERE POD.CPODT_CPOM_CODE = @CustomerPoCode
    AND POM.CPOM_CM_CODE = @CompanyCode
    AND POD.ES_DELETE = 0
    ORDER BY POD.CPODT_I_CODE;

END
GO

-- =============================================
-- Get Customer Master By ID
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetCustomerMasterById]
    @Id INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT 
        PM.P_CODE AS Id,
        PM.P_CM_COMP_ID AS CompanyId,
        PM.P_PARTY_CODE AS PartyCode,
        PM.P_NAME AS PartyName,
        PM.P_CONTACT AS ContactPerson,
        PM.P_ABBREVATION AS Abbreviation,
        PM.P_VEND_CODE AS VendorCode,
        PM.P_ADD1 AS Address,
        PM.P_PHONE AS Phone,
        PM.P_MOB AS Mobile,
        PM.P_EMAIL AS Email,
        PM.P_FAX AS FaxNo,
        PM.P_PIN_CODE AS PinCode,
        PM.P_A_CODE AS AreaCode,
        AM.A_DESC AS AreaName,
        PM.P_CUST_TYPE AS CustomerType,
        CTM.CTM_TYPE_DESC AS CustomerTypeName,
        PM.P_COUNTRY_CODE AS CountryCode,
        PM.P_SM_CODE AS StateCode,
        PM.P_CITY_CODE AS CityCode,
        PM.P_CATEGORY AS CategoryCode,
        PM.P_E_CODE AS EmployeeCode,
        PM.P_PAN AS PanNo,
        PM.P_CST AS CstNo,
        PM.P_VAT AS VatNo,
        PM.P_SER_TAX_NO AS ServiceTaxNo,
        PM.P_ECC_NO AS EccNo,
        PM.P_LBT_NO AS LbtNo,
        PM.P_LBT_NO AS GstNo,
        PM.P_EXC_RANGE AS ExciseRange,
        PM.P_EXC_DIV AS ExciseDivision,
        PM.P_EXC_COLLECTORATE AS ExciseCollectorate,
        PM.P_TALLY AS TallyName,
        PM.P_CREDITDAYS AS CreditDays,
        PM.P_TDS AS TdsPercentage,
        PM.P_ACTIVE_IND AS IsActive,
        PM.P_LBT_IND AS IsLbtApplicable
    FROM PARTY_MASTER PM
    LEFT JOIN AREA_MASTER AM ON PM.P_A_CODE = AM.A_CODE AND PM.P_CM_COMP_ID = AM.A_CM_COMP_ID
    LEFT JOIN CUSTOMER_TYPE_MASTER CTM ON PM.P_CUST_TYPE = CTM.CTM_TYPE_CODE AND PM.P_CM_COMP_ID = CTM.CTM_CM_COMP_ID
    WHERE PM.P_CODE = @Id 
      AND PM.P_CM_COMP_ID = @CompanyId
      AND PM.P_TYPE = 1;
END
GO

-- =============================================
-- Get All Customer Masters (Paged, Filtered, Sorted)
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetCustomerMasters]
    @CompanyId INT,
    @IsActive BIT = NULL,
    @AreaCode INT = NULL,
    @CustomerType VARCHAR(20) = NULL,
    @StateCode INT = NULL,
    @CityCode INT = NULL,
    @CategoryCode INT = NULL,
    @SearchTerm NVARCHAR(255) = NULL,
    @SortBy NVARCHAR(50) = 'PartyName',
    @SortDescending BIT = 0,
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @TotalRecords INT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;
    
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    
    -- Build WHERE clause dynamically
    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = N'
        SELECT 
            PM.P_CODE AS Id,
            PM.P_CM_COMP_ID AS CompanyId,
            PM.P_PARTY_CODE AS PartyCode,
            PM.P_NAME AS PartyName,
            PM.P_CONTACT AS ContactPerson,
            PM.P_ABBREVATION AS Abbreviation,
            PM.P_VEND_CODE AS VendorCode,
            PM.P_ADD1 AS Address,
            PM.P_PHONE AS Phone,
            PM.P_MOB AS Mobile,
            PM.P_EMAIL AS Email,
            PM.P_FAX AS FaxNo,
            PM.P_PIN_CODE AS PinCode,
            PM.P_A_CODE AS AreaCode,
            AM.A_DESC AS AreaName,
            PM.P_CUST_TYPE AS CustomerType,
            CTM.CTM_TYPE_DESC AS CustomerTypeName,
            PM.P_COUNTRY_CODE AS CountryCode,
            PM.P_SM_CODE AS StateCode,
            PM.P_CITY_CODE AS CityCode,
            PM.P_CATEGORY AS CategoryCode,
            PM.P_E_CODE AS EmployeeCode,
            PM.P_PAN AS PanNo,
            PM.P_CST AS CstNo,
            PM.P_VAT AS VatNo,
            PM.P_SER_TAX_NO AS ServiceTaxNo,
            PM.P_ECC_NO AS EccNo,
            PM.P_LBT_NO AS LbtNo,
            PM.P_EXC_RANGE AS ExciseRange,
            PM.P_EXC_DIV AS ExciseDivision,
            PM.P_EXC_COLLECTORATE AS ExciseCollectorate,
            PM.P_TALLY AS TallyName,
            PM.P_CREDITDAYS AS CreditDays,
            PM.P_TDS AS TdsPercentage,
            PM.P_ACTIVE_IND AS IsActive,
            PM.P_LBT_IND AS IsLbtApplicable
        FROM PARTY_MASTER PM
        LEFT JOIN AREA_MASTER AM ON PM.P_A_CODE = AM.A_CODE AND PM.P_CM_COMP_ID = AM.A_CM_COMP_ID
        LEFT JOIN CUSTOMER_TYPE_MASTER CTM ON PM.P_CUST_TYPE = CTM.CTM_TYPE_CODE AND PM.P_CM_COMP_ID = CTM.CTM_CM_COMP_ID
        WHERE PM.P_CM_COMP_ID = @CompanyId
          AND PM.P_TYPE = 1';
    
    -- Apply filters
    IF @IsActive IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_ACTIVE_IND = @IsActive';
        
    IF @AreaCode IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_A_CODE = @AreaCode';
        
    IF @CustomerType IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_CUST_TYPE = @CustomerType';
        
    IF @StateCode IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_SM_CODE = @StateCode';
        
    IF @CityCode IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_CITY_CODE = @CityCode';
        
    IF @CategoryCode IS NOT NULL
        SET @SQL = @SQL + N' AND PM.P_CATEGORY = @CategoryCode';
    
    -- Apply search
    IF @SearchTerm IS NOT NULL AND @SearchTerm <> ''
        SET @SQL = @SQL + N' AND (PM.P_NAME LIKE ''%'' + @SearchTerm + ''%'' 
                                OR PM.P_CONTACT LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_EMAIL LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_PHONE LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_MOB LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_ABBREVATION LIKE ''%'' + @SearchTerm + ''%'')';
    
    -- Get total count
    DECLARE @CountSQL NVARCHAR(MAX);
    SET @CountSQL = N'SELECT @TotalRecords = COUNT(*) FROM PARTY_MASTER PM 
        WHERE PM.P_CM_COMP_ID = @CompanyId AND PM.P_TYPE = 1';
        
    IF @IsActive IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_ACTIVE_IND = @IsActive';
    IF @AreaCode IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_A_CODE = @AreaCode';
    IF @CustomerType IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_CUST_TYPE = @CustomerType';
    IF @StateCode IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_SM_CODE = @StateCode';
    IF @CityCode IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_CITY_CODE = @CityCode';
    IF @CategoryCode IS NOT NULL
        SET @CountSQL = @CountSQL + N' AND PM.P_CATEGORY = @CategoryCode';
    IF @SearchTerm IS NOT NULL AND @SearchTerm <> ''
        SET @CountSQL = @CountSQL + N' AND (PM.P_NAME LIKE ''%'' + @SearchTerm + ''%'' 
                                OR PM.P_CONTACT LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_EMAIL LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_PHONE LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_MOB LIKE ''%'' + @SearchTerm + ''%''
                                OR PM.P_ABBREVATION LIKE ''%'' + @SearchTerm + ''%'')';
    
    EXEC sp_executesql @CountSQL, 
        N'@CompanyId INT, @IsActive BIT, @AreaCode INT, @CustomerType VARCHAR(20), @StateCode INT, @CityCode INT, @CategoryCode INT, @SearchTerm NVARCHAR(255), @TotalRecords INT OUTPUT',
        @CompanyId, @IsActive, @AreaCode, @CustomerType, @StateCode, @CityCode, @CategoryCode, @SearchTerm, @TotalRecords OUTPUT;
    
    -- Apply sorting
    SET @SQL = @SQL + N' ORDER BY ';
    
    IF @SortBy = 'PartyCode'
        SET @SQL = @SQL + N'PM.P_PARTY_CODE';
    ELSE IF @SortBy = 'AreaName'
        SET @SQL = @SQL + N'AM.A_DESC';
    ELSE IF @SortBy = 'CustomerTypeName'
        SET @SQL = @SQL + N'CTM.CTM_TYPE_DESC';
    ELSE
        SET @SQL = @SQL + N'PM.P_NAME';
    
    IF @SortDescending = 1
        SET @SQL = @SQL + N' DESC';
    ELSE
        SET @SQL = @SQL + N' ASC';
    
    -- Apply pagination
    SET @SQL = @SQL + N' OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY';
    
    -- Execute
    EXEC sp_executesql @SQL,
        N'@CompanyId INT, @IsActive BIT, @AreaCode INT, @CustomerType VARCHAR(20), @StateCode INT, @CityCode INT, @CategoryCode INT, @SearchTerm NVARCHAR(255), @Offset INT, @PageSize INT',
        @CompanyId, @IsActive, @AreaCode, @CustomerType, @StateCode, @CityCode, @CategoryCode, @SearchTerm, @Offset, @PageSize;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetCustomerPoById]
    @PoCode INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- Get Master Record with Customer Name, Project Name, Currency Name
        SELECT 
            m.CPOM_CODE AS PoCode,
            m.CPOM_P_CODE AS CustomerCode,
            p.P_NAME AS CustomerName,
            m.CPOM_PONO AS PoNumber,
            m.CPOM_DOC_NO AS DocumentNumber,
            m.CPOM_TYPE AS PoType,
            m.CPOM_DATE AS PoDate,
            m.CPOM_CR_DAYS AS CreditDays,
            m.CPOM_CM_COMP_ID AS CompanyId,
            m.CPOM_WORK_ODR_NO AS WorkOrderNumber,
            m.MODIFY AS IsLocked,
            m.ES_DELETE AS IsDeleted,
            m.CPOM_PAY_TERM AS PaymentTerms,
            m.CPOM_AUTH_FLG AS IsAuthorized,
            m.CPOM_PO_DATE AS CustomerPoDate,
            m.CPOM_QE_CODE AS QuotationCode,
            m.CPOM_T_NAME AS TaxName,
            m.CPOM_T_PER AS TaxPercentage,
            m.CPOM_T_AMT AS TaxAmount,
            m.CPOM_EXC_PER AS ExcisePercentage,
            m.CPOM_EXC_EDU_PER AS ExciseEducationPercentage,
            m.CPOM_EXC_HEDU_PER AS ExciseHigherEducationPercentage,
            m.CPOM_BASIC_AMT AS BasicAmount,
            m.CPOM_DISCOUNT_PER AS DiscountPercentage,
            m.CPOM_DISCOUNT_AMT AS DiscountAmount,
            m.CPOM_DISCOUNT_REASON AS DiscountReason,
            m.CPOM_DEVIATION_AMT AS DeviationAmount,
            m.CPOM_DEVIATION_REASON AS DeviationReason,
            m.CPOM_PACKING_AMT AS PackingAmount,
            m.CPOM_EXC_AMT AS ExciseAmount,
            m.CPOM_ROUNDING AS RoundingAmount,
            m.CPOM_GRAND_TOT AS GrandTotal,
            m.CPOM_INV_FLAG AS InvoiceGenerated,
            m.CPOM_AM_COUNT AS AmendmentCount,
            m.CPOM_FINAL_DEST AS FinalDestination,
            m.CPOM_PRE_CARR_BY AS PreCarriageBy,
            m.CPOM_PORT_LOAD AS PortOfLoading,
            m.CPOM_PORT_DIS AS PortOfDischarge,
            m.CPOM_PLACE_DEL AS PlaceOfDelivery,
            m.CPOM_BUYER_NAME AS BuyerName,
            m.CPOM_BUYER_ADD AS BuyerAddress,
            m.CPOM_CURR_CODE AS CurrencyCode,
            m.CPOM_AM_DATE AS AmendmentDate,
            m.CPOM_INQ_CODE AS InquiryCode,
            m.CPOM_IS_VERBAL AS IsVerbalOrder,
            m.CPOM_PROJECT_CODE AS ProjectCode,
            m.CPOM_PROJECT_NAME AS ProjectName
        FROM CUSTPO_MASTER m
        INNER JOIN PARTY_MASTER p ON m.CPOM_P_CODE = p.P_CODE
        WHERE 
            m.CPOM_CODE = @PoCode 
            AND m.CPOM_CM_COMP_ID = @CompanyId
            AND m.ES_DELETE = 0;

        -- Get Detail Records with Item Name, UOM Name, Store Name, Currency Name
        SELECT 
            d.CPOD_CPOM_CODE AS PoCode,
            d.CPOD_I_CODE AS ItemCode,
            i.I_CODENO AS ItemCodeName,
            i.I_NAME AS ItemName,
            d.CPOD_UOM_CODE AS UomCode,
            u.I_UOM_NAME AS UomName,
            d.CPOD_ORD_QTY AS OrderedQuantity,
            d.CPOD_RATE AS Rate,
            d.CPOD_AMT AS Amount,
            d.CPOD_DESC AS Description,
            d.CPOD_CUST_I_CODE AS CustomerItemCode,
            d.CPOD_CUST_I_NAME AS CustomerItemName,
            d.CPOD_STATUS AS Status,
            d.CPOD_DISPACH AS DispatchedQuantity,
            d.CPOD_IS_ORDER AS IsOrder,
            d.CPOD_ST_CODE AS StoreCode,
            d.CPOD_CURR_CODE AS CurrencyCode,
            d.CPOD_WO_QTY AS WorkOrderQuantity,
            d.CPOD_MODNO AS ModificationNumber,
            d.CPOD_MODDATE AS ModificationDate,
            d.CPOD_AMORTRATE AS AmortizationRate,
            d.CPOD_DIEAMORTRATE AS DieAmortizationRate,
            d.CPOD_DISC_PER AS DiscountPercentage,
            d.CPOD_DISC_AMT AS DiscountAmount,
            d.CPOD_ST_CODE AS TaxCategoryCode
        FROM CUSTPO_DETAIL d
        INNER JOIN ITEM_MASTER i ON d.CPOD_I_CODE = i.I_CODE
        INNER JOIN ITEM_UNIT_MASTER u ON d.CPOD_UOM_CODE = u.I_UOM_CODE
        WHERE d.CPOD_CPOM_CODE = @PoCode
        ORDER BY d.CPOD_I_CODE;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Stored Procedure: ERP_GetCustomerPoPrintData
-- Purpose: Fetch all data required for Customer PO (Sales Order) PDF printing
-- Returns: Multiple result sets for different sections of the PO
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetCustomerPoPrintData]
    @PoCode INT,
    @CompanyId INT,
    @CompanyCode INT
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Result Set 1: Company Information
    SELECT 
        CM.CM_NAME AS CompanyName,
        ISNULL(CM.CM_ADDRESS1, '') AS FullAddress,
        CM.CM_GST_NO AS GstinNo,
        CM.CM_PHONENO1 AS Phone,
        CM.CM_FAXNO AS Fax,
        CM.CM_EMAILID AS Email,
        CM.CM_WEBSITE AS Website
    FROM COMPANY_MASTER CM
    WHERE CM.CM_CODE = @CompanyCode;
    
    -- Result Set 2: PO Header
    SELECT 
        ISNULL(CPM.CPOM_DOC_NO, CPM.CPOM_CODE) AS SaleOrderNo,
        CPM.CPOM_DATE AS SaleOrderDate,
        CPM.CPOM_PONO AS PoNo,
        CPM.CPOM_PO_DATE AS PoDate,
        CPM.CPOM_FINAL_DEST AS Consignee,
        CPM.CPOM_PRE_CARR_BY AS TransportThrough,
        CPM.CPOM_PLACE_DEL AS DeliveryTerms,
        CPM.CPOM_PAY_TERM AS Narrations
    FROM CUSTPO_MASTER CPM
    WHERE CPM.CPOM_CODE = @PoCode
        AND CPM.CPOM_CM_COMP_ID = @CompanyId;
    
    -- Result Set 3: Customer Information
    SELECT 
        P.P_NAME AS Name,
        CONCAT(
            ISNULL(P.P_ADD1, ''), 
            CASE WHEN P.P_CITY IS NOT NULL AND P.P_CITY != '' THEN ', ' + P.P_CITY ELSE '' END
        ) AS Address
    FROM CUSTPO_MASTER CPM
    INNER JOIN PARTY_MASTER P ON P.P_CODE = CPM.CPOM_P_CODE
    WHERE CPM.CPOM_CODE = @PoCode
        AND CPM.CPOM_CM_COMP_ID = @CompanyId;
    
    -- Result Set 4: PO Line Items (Ordered by order quantity descending)
    SELECT 
        ROW_NUMBER() OVER (ORDER BY d.CPOD_ORD_QTY DESC) AS SrNo,
        CONCAT(i.I_NAME, ' (', i.I_CODENO, ')') AS ItemName,
        d.CPOD_ORD_QTY AS Qty,
        u.I_UOM_NAME AS Unit,
        d.CPOD_RATE AS Rate,
        d.CPOD_AMT AS Amount
    FROM CUSTPO_DETAIL d
    INNER JOIN ITEM_MASTER i ON i.I_CODE = d.CPOD_I_CODE
    INNER JOIN ITEM_UNIT_MASTER u ON u.I_UOM_CODE = d.CPOD_UOM_CODE
    WHERE d.CPOD_CPOM_CODE = @PoCode
    ORDER BY d.CPOD_ORD_QTY DESC;
    
    -- Result Set 5: Totals
    -- Use CPOM_T_PER if available, otherwise default to 18% GST (9% CGST + 9% SGST)
    SELECT 
        ISNULL(SUM(d.CPOD_ORD_QTY), 0) AS TotalQty,
        ISNULL(SUM(d.CPOD_AMT), 0) AS AssessableValue,
        ISNULL((SUM(d.CPOD_AMT) * COALESCE(m.CPOM_T_PER, 18.0) / 100) / 2, 0) AS CentralTax,
        ISNULL((SUM(d.CPOD_AMT) * COALESCE(m.CPOM_T_PER, 18.0) / 100) / 2, 0) AS StateUnionTerritoryTax,
        ISNULL(SUM(d.CPOD_AMT) + (SUM(d.CPOD_AMT) * COALESCE(m.CPOM_T_PER, 18.0) / 100), 0) AS TotalAmount
    FROM CUSTPO_MASTER m
    LEFT JOIN CUSTPO_DETAIL d ON d.CPOD_CPOM_CODE = m.CPOM_CODE
    WHERE m.CPOM_CODE = @PoCode
        AND m.CPOM_CM_COMP_ID = @CompanyId
    GROUP BY m.CPOM_T_PER;
    
END
GO

