CREATE OR ALTER PROCEDURE [dbo].[ERP_GetCustomerTypeMasters]
    @CTM_CM_COMP_ID INT = NULL,
    @CTM_TYPE_CODE VARCHAR(50) = NULL,
    @CTM_TYPE_DESC VARCHAR(150) = NULL,
    @CTM_FIRST_LETTER VARCHAR(50) = NULL,
    @SearchTerm NVARCHAR(255) = NULL,
    @SortBy VARCHAR(50) = 'TypeDescription',
    @SortDirection VARCHAR(4) = 'ASC',
    @PageNumber INT = 1,
    @PageSize INT = 10,
    @TotalCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Build the WHERE clause dynamically
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @CountSQL NVARCHAR(MAX);
    DECLARE @WhereClause NVARCHAR(MAX) = ' WHERE ES_DELETE = 0';

    IF @CTM_CM_COMP_ID IS NOT NULL
        SET @WhereClause = @WhereClause + ' AND CTM_CM_COMP_ID = @CTM_CM_COMP_ID';

    IF @CTM_TYPE_CODE IS NOT NULL AND @CTM_TYPE_CODE <> ''
        SET @WhereClause = @WhereClause + ' AND CTM_TYPE_CODE LIKE ''%'' + @CTM_TYPE_CODE + ''%''';

    IF @CTM_TYPE_DESC IS NOT NULL AND @CTM_TYPE_DESC <> ''
        SET @WhereClause = @WhereClause + ' AND CTM_TYPE_DESC LIKE ''%'' + @CTM_TYPE_DESC + ''%''';

    IF @CTM_FIRST_LETTER IS NOT NULL AND @CTM_FIRST_LETTER <> ''
        SET @WhereClause = @WhereClause + ' AND CTM_FIRST_LETTER LIKE ''%'' + @CTM_FIRST_LETTER + ''%''';

    IF @SearchTerm IS NOT NULL AND @SearchTerm <> ''
        SET @WhereClause = @WhereClause + ' AND (CTM_TYPE_CODE LIKE ''%'' + @SearchTerm + ''%'' 
                                                   OR CTM_TYPE_DESC LIKE ''%'' + @SearchTerm + ''%'' 
                                                   OR CTM_FIRST_LETTER LIKE ''%'' + @SearchTerm + ''%'')';

    -- Map SortBy to actual column names
    DECLARE @OrderByColumn VARCHAR(50);
    SET @OrderByColumn = CASE @SortBy
        WHEN 'TypeCode' THEN 'CTM_TYPE_CODE'
        WHEN 'TypeDescription' THEN 'CTM_TYPE_DESC'
        WHEN 'FirstLetter' THEN 'CTM_FIRST_LETTER'
        ELSE 'CTM_TYPE_DESC'
    END;

    -- Get total count
    SET @CountSQL = 'SELECT @TotalCount = COUNT(*) FROM CUSTOMER_TYPE_MASTER' + @WhereClause;

    EXEC sp_executesql @CountSQL,
        N'@CTM_CM_COMP_ID INT, @CTM_TYPE_CODE VARCHAR(50), @CTM_TYPE_DESC VARCHAR(150), 
          @CTM_FIRST_LETTER VARCHAR(50), @SearchTerm NVARCHAR(255), @TotalCount INT OUTPUT',
        @CTM_CM_COMP_ID, @CTM_TYPE_CODE, @CTM_TYPE_DESC, @CTM_FIRST_LETTER, @SearchTerm, @TotalCount OUTPUT;

    -- Get paginated results
    SET @SQL = 'SELECT 
                    CTM_CODE,
                    CTM_CM_COMP_ID,
                    CTM_TYPE_CODE,
                    CTM_TYPE_DESC,
                    CTM_FIRST_LETTER,
                    ES_DELETE,
                    MODIFY
                FROM CUSTOMER_TYPE_MASTER' + @WhereClause + '
                ORDER BY ' + @OrderByColumn + ' ' + @SortDirection + '
                OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY';

    EXEC sp_executesql @SQL,
        N'@CTM_CM_COMP_ID INT, @CTM_TYPE_CODE VARCHAR(50), @CTM_TYPE_DESC VARCHAR(150), 
          @CTM_FIRST_LETTER VARCHAR(50), @SearchTerm NVARCHAR(255), @Offset INT, @PageSize INT',
        @CTM_CM_COMP_ID, @CTM_TYPE_CODE, @CTM_TYPE_DESC, @CTM_FIRST_LETTER, @SearchTerm, @Offset, @PageSize;
END;
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetFinancialYearsByCompanyId]
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Query matches legacy: select distinct CM_CODE, 'From  ' +convert(varchar(10),CM_OPENING_DATE,103)+' To '+ convert(varchar(10),CM_CLOSING_DATE,103)as FINANCIAL from COMPANY_MASTER where CM_ID=<companyId> order by CM_CODE desc
    SELECT DISTINCT 
        CM_CODE AS Id,
        'From ' + CONVERT(VARCHAR(10), CM_OPENING_DATE, 103) + ' To ' + CONVERT(VARCHAR(10), CM_CLOSING_DATE, 103) AS DisplayName,
        CM_CODE AS FinancialYearCode,
        CONVERT(VARCHAR(10), CM_OPENING_DATE, 103) AS OpeningDate,
        CONVERT(VARCHAR(10), CM_CLOSING_DATE, 103) AS ClosingDate
    FROM COMPANY_MASTER 
    WHERE CM_ID = @CompanyId 
    ORDER BY CM_CODE DESC;
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Gets item details for Tax Invoice form (Unit, HSN Code, Stock Quantity)
-- Used when an item is selected in the Tax Invoice form
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetItemDetailsForTaxInvoice]
    @ItemCode INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        SELECT 
            -- Unit Information
            ISNULL(IM.I_UOM_CODE, 0) AS UomCode,
            ISNULL(UOM.I_UOM_NAME, '') AS UomName,
            
            -- HSN Code (from EXCISE_TARIFF_MASTER via I_E_CODE)
            ISNULL(ETM.E_TARIFF_NO, '') AS HsnCode,
            
            -- Stock Quantity (sum from STOCK_LEDGER where STL_STORE_TYPE = -2147483648)
            ISNULL((
                SELECT SUM(STL_DOC_QTY)
                FROM STOCK_LEDGER
                WHERE STL_I_CODE = @ItemCode
                  AND STL_STORE_TYPE = -2147483648
            ), 0) AS StockQuantity
            
        FROM ITEM_MASTER IM
        LEFT JOIN ITEM_UNIT_MASTER UOM ON UOM.I_UOM_CODE = IM.I_UOM_CODE AND ISNULL(UOM.ES_DELETE, 0) = 0
        LEFT JOIN EXCISE_TARIFF_MASTER ETM ON ETM.E_CODE = IM.I_E_CODE AND ISNULL(ETM.ES_DELETE, 0) = 0
        WHERE IM.I_CODE = @ItemCode
          AND IM.I_CM_COMP_ID = @CompanyId
          AND ISNULL(IM.ES_DELETE, 0) = 0;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Gets distinct item codes, item code numbers, and item names for Tax Invoice form
--              Based on legacy LoadICode() and LoadIName() methods from TaxInvoice.aspx.cs
--              Called when customer is selected to populate Item Code and Item Name dropdowns
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetItemsForTaxInvoiceByCustomer]
    @CustomerCode INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        SELECT DISTINCT 
            IM.I_CODE AS ItemCode,
            IM.I_CODENO AS ItemCodeNo,
            IM.I_NAME AS ItemName
        FROM ITEM_MASTER IM
        INNER JOIN CUSTPO_DETAIL CPD ON CPD.CPOD_I_CODE = IM.I_CODE
        INNER JOIN CUSTPO_MASTER CPM ON CPM.CPOM_CODE = CPD.CPOD_CPOM_CODE
        WHERE CPM.ES_DELETE = 0
          AND (
              (CPD.CPOD_ORD_QTY - CPD.CPOD_DISPACH) > 0 
              OR CPM.CPOM_CODE = CPD.CPOD_CPOM_CODE
          )
          AND CPM.CPOM_P_CODE = @CustomerCode
          AND IM.I_CM_COMP_ID = @CompanyId
          AND ISNULL(IM.ES_DELETE, 0) = 0
        ORDER BY IM.I_CODENO ASC;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-10-24
-- Description: Gets available stock for an item by summing STOCK_LEDGER entries
-- Note: This uses STOCK_LEDGER (sum of all transactions) instead of ITEM_MASTER.I_QTY
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetItemStock]
    @ItemCode INT,
    @CompanyCode INT,
    @AvailableQuantity FLOAT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        -- Sum all stock movements for this item
        -- Positive = Stock IN (Purchases, Returns, etc.)
        -- Negative = Stock OUT (Sales, Issues, etc.)
        SELECT @AvailableQuantity = ISNULL(SUM(STL_DOC_QTY), 0)
        FROM STOCK_LEDGER
        WHERE STL_I_CODE = @ItemCode;

        -- If no stock ledger entries found, return 0
        IF @AvailableQuantity IS NULL
            SET @AvailableQuantity = 0;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

