        INM_S_TAX_AMT AS ServiceTaxAmount,
        INM_BEXCISE AS BasicExcisePercentage,
        INM_BE_AMT AS BasicExciseAmount,
        INM_EDUC_CESS AS EducationCessPercentage,
        INM_EDUC_AMT AS EducationCessAmount,
        INM_H_EDUC_CESS AS HigherEducationCessPercentage,
        INM_H_EDUC_AMT AS HigherEducationCessAmount,
        INM_DISC AS DiscountPercentage,
        INM_DISC_AMT AS DiscountAmount,
        INM_PACK_AMT AS PackingAmount,
        INM_PACK_DCES AS PackingDescription,
        INM_T_CODE AS TaxCode,
        INM_T_AMT AS TaxAmount,
        INM_G_AMT AS GrossAmount,
        INM_G_AMORT_AMT AS GrossAmortizationAmount,
        INM_TAX_TCS AS TcsPercentage,
        INM_TAX_TCS_AMT AS TcsAmount,
        INM_FREIGHT AS FreightCharges,
        INM_VEH_NO AS VehicleNumber,
        INM_TRANSPORT AS TransportName,
        INM_ISSUE_DATE AS IssueDate,
        INM_REMOVAL_DATE AS RemovalDate,
        INM_STO_LOC AS StorageLocation,
        INM_REMARK AS Remarks,
        INM_C_DAYS AS CreditDays,
        INM_ASN_NO AS AsnNumber,
        INM_NATURE_PRO AS NatureOfProduct,
        INM_PREPARE_BY AS PreparedBy,
        INM_REWORK_FLAG AS ReworkFlag,
        INM_TALLYTNF AS TallyTransferFlag,
        INM_TEMP_TALLYTNF AS TempTallyTransferFlag,
        INM_TRIFF_NO AS TariffNumber,
        INM_TRIFF_NAME AS TariffName,
        INM_TALLYTNF1 AS TallyTransferFlag1,
        INM_TEMP_TALLYTNF1 AS TempTallyTransferFlag1,
        INM_TRANS_AMT AS TransportAmount,
        INM_COURIER_AMT AS CourierAmount,
        INM_SER_PER AS ServicePercentage,
        INM_SER_AMT AS ServiceAmount,
        INM_SER_EDUC_CESS AS ServiceEducationCessPercentage,
        INM_SER_EDUC_CESS_AMT AS ServiceEducationCessAmount,
        INM_SER_H_EDUC_CESS AS ServiceHigherEducationCessPercentage,
        INM_SER_H_EDUC_CESS_AMT AS ServiceHigherEducationCessAmount,
        INM_DEL_ADD AS DeliveryAddress,
        INM_P_CODE_ALT AS AlternateCustomerCode,
        INM_OTHER_AMT AS OtherAmount,
        INM_LR_NO AS LrNumber,
        INM_LR_DATE AS LrDate,
        INM_BUYER_NAME AS BuyerName,
        INM_BUYTER_ADD AS BuyerAddress,
        INM_INSURANCE AS InsuranceAmount,
        INM_FINAL_DEST AS FinalDestination,
        INM_PRE_CARRIAGE AS PreCarriage,
        INM_PORT_OF_LOAD AS PortOfLoading,
        INM_PORT_OF_DISCH AS PortOfDischarge,
        INM_PLACE_OF_DEL AS PlaceOfDelivery,
        INM_CURR_CODE AS CurrencyCode,
        INM_CLEARANCE AS Clearance,
        INM_FLIGHT_NO AS FlightNumber,
        INM_MFG_DATE AS ManufacturingDate,
        INM_EXP_DATE AS ExpiryDate,
        INM_CURR_RATE AS CurrencyRate,
        INM_AUTHO_SIGN AS AuthorizedSignatory,
        INM_AREA_FORM_NO AS AreaFormNumber,
        INM_FORM_DATE AS FormDate,
        INM_SHIPMENT AS Shipment,
        INM_CENVAT_AC_NO AS CenvatAccountNumber,
        INM_BOND_NO AS BondNumber,
        INM_BOND_DATE AS BondDate,
        INM_UT1_FILE_NO AS Ut1FileNumber,
        INM_FILE_NO AS FileNumber,
        INM_EXPORT_FLAG AS ExportFlag,
        INM_VALID_DATE AS ValidityDate,
        INM_EXA_BOXES AS ExaminationBoxes,
        INM_TOD AS TermsOfDelivery,
        INM_TOP AS TermsOfPayment,
        INM_VOY_NO AS VoyageNumber,
        INM_PLACE_REC AS PlaceOfReceipt,
        INM_M_NO AS MarksAndNumbers,
        INM_NOS_PACK AS NumberOfPackages,
        INM_UN_NO AS UnNumber,
        INM_HAZ AS HazardClass,
        INM_HS_CODENO AS HsCodeNumber,
        INM_CONTA_NO AS ContainerNumber,
        INM_SEAL_NO AS SealNumber,
        INM_OTS_NO AS OtsNumber,
        INM_CONTRY_ORIGIN AS CountryOfOrigin,
        INM_COUNTRY_DEST AS CountryOfDestination,
        INM_TRANSPORT_BY AS TransportBy,
        INM_ARE_REMARK AS AreaRemarks,
        INM_CARRIER_NAME AS CarrierName,
        INM_CARRIER_BOOK_NO AS CarrierBookingNumber,
        INM_SHIP_NAME AS ShipName,
        INM_TECH_NAME AS TechnicalName,
        INM_OUT_PAKGS AS OuterPackaging,
        INM_INR_PAKG AS InnerPackaging,
        INM_SUB_CLASS AS SubsidiaryClass,
        INM_UN_PAK_GRP AS UnPackingGroup,
        INM_UN_PAK_CODE AS UnPackingCode,
        INM_EMS_NO AS EmsNumber,
        INM_FLASH_POINT AS FlashPoint,
        INM_MARINE_POLLT AS MarinePollutant,
        INM_SHIP_DECLAR AS ShipperDeclaration,
        INM_IEC_NO AS IecNumber,
        INM_IEC_DATE AS IecDate,
        INM_CEN_EXC_REG AS CentralExciseRegistration,
        INM_DATE_OF_EXAM AS DateOfExamination,
        INM_SUP_C_EXC_NAME AS SuperintendentExciseName,
        INM_INSP_C_EXC_NAME AS InspectorExciseName,
        INM_CUST_SEAL_NO AS CustomsSealNumber,
        INM_PER_E_NO AS PermitENumber,
        INM_IS_TALLY_TRANS AS IsTallyTransferred,
        INM_NONCARGO_NOPAKG AS NonCargoNumberOfPackages,
        INM_SHIPP_BILL_NO AS ShippingBillNumber,
        INM_ACCESSIBLE_AMT AS AccessibleAmount,
        INM_TAXABLE_AMT AS TaxableAmount,
        INM_ROUNDING_AMT AS RoundingAmount,
        INM_ADV_DUTY AS AdvanceDuty,
        INM_OCTRI_AMT AS OctriAmount,
        INM_IS_SUPPLIMENT AS IsSuppliment,
        INM_ISSU_TIME AS IssueTime,
        INM_REMOVEL_TIME AS RemovalTime,
        INM_LC_NO AS LcNumber,
        INM_LC_DATE AS LcDate,
        INM_TRANSPORT_OWNER AS TransportOwner,
        INM_TRANSPORT_ADDRESS AS TransportAddress,
        INM_TNO AS TNumber,
        INM_TRAY_CODE AS TrayCode,
        INM_TRAY_QTY AS TrayQuantity,
        INM_ADDRESS AS Address,
        INM_STATE AS StateCode,
        SM.SM_NAME AS StateName,
        INM_HSN_CODE AS HsnCode,
        INM_ELECTRREFNUM AS ElectronicReferenceNumber,
        INM_TERMSNCONDITIONS AS TermsAndConditions,
        INM_AUTHORIZEDNAME AS AuthorizedName,
        INM_ADDRESS_SELECTED AS AddressSelected,
        I.ES_DELETE AS IsDeleted,
        I.MODIFY AS IsModifyLocked
    FROM INVOICE_MASTER I
    LEFT JOIN PARTY_MASTER P ON I.INM_P_CODE = P.P_CODE
    LEFT JOIN STATE_MASTER SM ON I.INM_STATE = SM.SM_CODE
    WHERE I.INM_CODE = @InvoiceCode AND I.INM_CM_CODE = @CompanyCode;

    -- Return Invoice Details
    SELECT 
        IND_INM_CODE AS InvoiceMasterCode,
        IND_I_CODE AS ItemCode,
        IM.I_CODENO AS ItemCode_Display,
        IM.I_NAME AS ItemName,
        IND_UOM_CODE AS UomCode,
        IND_CPOM_CODE AS CustomerPoCode,
        IND_INQTY AS InvoiceQuantity,
        IND_RATE AS Rate,
        IND_CON_QTY AS ConversionQuantity,
        IND_AMORT_RATE AS AmortizationRate,
        IND_NO_PACK AS NumberOfPackages,
        IND_PACK_DESC AS PackageDescription,
        IND_QTY_PACK AS QuantityPerPack,
        IND_AMT AS Amount,
        IND_DC_NO AS DeliveryChallanNumbers,
        IND_DC_DATE AS DeliveryChallanDates,
        IND_EX_NO AS ExciseNumbers,
        IND_PROCESS_CODE AS ProcessCode,
        IND_GIN_NO AS GinNumber,
        IND_GIN_DATE AS GinDate,
        IND_GIN_RCPT AS GinReceipt,
        IND_MR_CODE AS MrCode,
        IND_GIN_ACCP AS GinAcceptance,
        IND_EX_AMT AS ExciseAmount,
        IND_E_CESS_AMT AS EducationCessAmount,
        IND_SH_CESS_AMT AS SecondaryHigherEducationCessAmount,
        E_BASIC_CentralT AS CgstPercentage,
        E_EDU_CESS_State AS SgstPercentage,
        E_H_EDU_Integrated AS IgstPercentage,
        IND_SR_NO AS SerialNumber,
        IND_REMARK AS Remarks,
        IND_IWM_CODE AS ItemWarehouseCode,
        IND_ACT_WEIGHT AS ActualWeight,
        IND_SIZE AS Size,
        IND_SUBHEADING AS SubHeading,
        IND_BACHNO AS BatchNumber,
        IND_PAK_QTY AS PackingQuantity,
        IND_GROSS_WEIGHT AS GrossWeight,
        IND_NET_WEIGHT AS NetWeight,
        IND_SIZE_OF_BOX AS SizeOfBox,
        IND_NO_OF_BARRELS AS NumberOfBarrels,
        IND_NO_OF_PACK_DESC AS NumberOfPackagesDescription,
        IND_CONTAINER_NO AS ContainerNumber,
        IND_REFUNDABLE_QTY AS RefundableQuantity,
        IND_AMORTRATE AS AmortRate,
        IND_AMORTAMT AS AmortAmount,
        IND_HSN_CODE AS HsnCode,
        IND_STORE_CODE AS StoreCode,
        ID.ES_DELETE AS IsDeleted
    FROM INVOICE_DETAIL ID
    LEFT JOIN ITEM_MASTER IM ON ID.IND_I_CODE = IM.I_CODE
    WHERE ID.IND_INM_CODE = @InvoiceCode AND ID.ES_DELETE = 0
    ORDER BY ID.IND_I_CODE;

END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetTaxInvoicePrintData]
    @InvoiceCode INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        -- =========================================================================
        -- 1. GET COMPANY INFORMATION
        -- =========================================================================
        SELECT 
            CM_NAME AS CompanyName,
            ISNULL(CM_ADDRESS1, '') + CASE WHEN ISNULL(CM_ADDRESS2, '') <> '' THEN ', ' + CM_ADDRESS2 ELSE '' END + 
            CASE WHEN ISNULL(CM_ADDRESS3, '') <> '' THEN ', ' + CM_ADDRESS3 ELSE '' END AS Address,
            ISNULL(CM_CITY, '') AS City,
            ISNULL(CM_STATE, '') AS State,
            '' AS StateCode, -- Need to add if column exists
            '' AS PinCode,   -- Need to add if column exists
            ISNULL(CM_PHONENO1, '') AS Phone,
            ISNULL(CM_FAXNO, '') AS Fax,
            ISNULL(CM_EMAILID, '') AS Email,
            ISNULL(CM_WEBSITE, '') AS Website,
            ISNULL(CM_GST_NO, '') AS GstNumber,
            ISNULL(CM_PAN_NO, '') AS PanNumber,
            ISNULL(CM_CIN_NO, '') AS CinNumber,
            ISNULL(CM_VAT_TIN_NO, '') AS VatTin,
            ISNULL(CM_CST_NO, '') AS CstTin,
            '' AS EccNumber,
            '' AS IsoNumber,
            '' AS RegistrationNumber,
            NULL AS LoPath
        FROM COMPANY_MASTER CM
        INNER JOIN INVOICE_MASTER INM ON INM.INM_CM_CODE = CM.CM_CODE
        WHERE CM.CM_ID = @CompanyId 
        AND INM.INM_CODE = @InvoiceCode
        AND ISNULL(CM.CM_DELETE_FLAG, 0) = 0;

        -- =========================================================================
        -- 2. GET INVOICE MASTER INFORMATION
        -- =========================================================================
        SELECT 
            INM_CODE AS InvoiceCode,
            INM_NO AS InvoiceNumber,
            INM_DATE AS InvoiceDate,
            ISNULL(INM_TNO, '') AS ReferenceNumber,  -- This contains the Serial Number like "SUN252605704"
            ISNULL((SELECT TOP 1 CPOM_PONO FROM CUSTPO_MASTER WHERE CPOM_CODE = INM_CPOM_CODE AND ES_DELETE = 0), '') AS PoNumber,
            (SELECT TOP 1 CPOM_PO_DATE FROM CUSTPO_MASTER WHERE CPOM_CODE = INM_CPOM_CODE AND ES_DELETE = 0) AS PoDate,
            ISNULL(INM_TRANSPORT, '') AS TransportName,
            ISNULL(INM_VEH_NO, '') AS VehicleNumber,
            ISNULL(INM_LR_NO, '') AS LrNumber,
            INM_LR_DATE AS LrDate,
            ISNULL(INM_NET_AMT, 0) AS BasicAmount,
            ISNULL(INM_DISC, 0) AS DiscountPercentage,
            ISNULL(INM_DISC_AMT, 0) AS DiscountAmount,
            ISNULL(INM_PACK_AMT, 0) AS PackingAmount,
            ISNULL(INM_FREIGHT, 0) AS FreightAmount,
            ISNULL(INM_INSURANCE, 0) AS InsuranceAmount,
            ISNULL(INM_OTHER_AMT, 0) AS OtherCharges,
            ISNULL(INM_ROUNDING_AMT, 0) AS RoundingAmount,
            ISNULL(INM_G_AMT, 0) AS GrandTotal,
            ISNULL(INM_REMARK, '') AS Remarks,
            ISNULL(INM_TERMSNCONDITIONS, '') AS TermsAndConditions
        FROM INVOICE_MASTER
        INNER JOIN COMPANY_MASTER CM ON CM.CM_CODE = INM_CM_CODE AND CM.CM_ID = @CompanyId AND ISNULL(CM.CM_DELETE_FLAG, 0) = 0
        WHERE INM_CODE = @InvoiceCode 
        AND INVOICE_MASTER.ES_DELETE = 0;

        -- =========================================================================
        -- 3. GET CUSTOMER INFORMATION
        -- =========================================================================
        SELECT 
            P_CODE AS CustomerCode,
            P_NAME AS CustomerName,
            ISNULL(P_ADD1, '') AS BillingAddress,
            ISNULL(P_DELIVERY_ADD, P_ADD1) AS ShippingAddress,
            ISNULL(P_CITY, '') AS City,
            ISNULL(SM.SM_NAME, '') AS State,
            ISNULL(SM.SM_STATE_CODE, '') AS StateCode,
            ISNULL(P_PIN_CODE, '') AS PinCode,
            ISNULL(P_GST_NO, '') AS GstNumber,
            ISNULL(P_PAN, '') AS PanNumber,
            ISNULL(P_CONTACT, '') AS ContactPerson,
            ISNULL(P_PHONE, '') AS Phone,
            ISNULL(P_EMAIL, '') AS Email
        FROM INVOICE_MASTER
        INNER JOIN PARTY_MASTER ON P_CODE = INM_P_CODE
        LEFT JOIN STATE_MASTER SM ON SM.SM_CODE = P_SM_CODE AND SM.ES_DELETE = 0
        WHERE INM_CODE = @InvoiceCode
        AND INVOICE_MASTER.ES_DELETE = 0;

        -- =========================================================================
        -- 4. GET INVOICE LINE ITEMS WITH TAX DETAILS
        -- =========================================================================
        SELECT 
            ROW_NUMBER() OVER (ORDER BY IND_INM_CODE, IND_I_CODE) AS SerialNumber,
            IND_I_CODE AS ItemCode,
            ISNULL(I.I_NAME, '') AS ItemName,
            ISNULL(IND_REMARK, I.I_NAME) AS ItemDescription,
            ISNULL(IND_HSN_CODE, '') AS HsnCode,
            '' AS CustomerItemCode,  -- Add if column exists
            ISNULL(IND_INQTY, 0) AS Quantity,
            ISNULL(U.I_UOM_NAME, 'NOS') AS UnitOfMeasurement,
            ISNULL(IND_RATE, 0) AS Rate,
            ISNULL(IND_AMT, 0) AS Amount,
            ISNULL(IND_NO_PACK, 0) AS NumberOfPackages,
            ISNULL(IND_PACK_DESC, '') AS PackingDescription,
            
            -- Tax Calculations (Percentages are stored, amounts need to be calculated)
            ISNULL(IND_AMT, 0) AS TaxableAmount,
            ISNULL(E_BASIC_CentralT, 0) AS CgstPercentage,
            ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_BASIC_CentralT, 0) / 100, 2) AS CgstAmount,
            ISNULL(E_EDU_CESS_State, 0) AS SgstPercentage,
            ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_EDU_CESS_State, 0) / 100, 2) AS SgstAmount,
            ISNULL(E_H_EDU_Integrated, 0) AS IgstPercentage,
            ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_H_EDU_Integrated, 0) / 100, 2) AS IgstAmount,
            
            -- Total Tax = CGST + SGST + IGST
            ROUND(
                (ISNULL(IND_AMT, 0) * ISNULL(E_BASIC_CentralT, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_EDU_CESS_State, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_H_EDU_Integrated, 0) / 100), 2
            ) AS TotalTax,
            
            -- Total Amount = Taxable Amount + Total Tax
            ROUND(ISNULL(IND_AMT, 0) + 
                (ISNULL(IND_AMT, 0) * ISNULL(E_BASIC_CentralT, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_EDU_CESS_State, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_H_EDU_Integrated, 0) / 100), 2
            ) AS TotalAmount,
            
            ISNULL(IND_AMORTAMT, 0) AS AmortizationAmount
        FROM INVOICE_DETAIL
        INNER JOIN ITEM_MASTER I ON I.I_CODE = IND_I_CODE
        LEFT JOIN ITEM_UNIT_MASTER U ON U.I_UOM_CODE = ISNULL(IND_UOM_CODE, I.I_UOM_CODE)
        WHERE IND_INM_CODE = @InvoiceCode
        AND INVOICE_DETAIL.ES_DELETE = 0
        ORDER BY IND_INM_CODE, IND_I_CODE;

        -- =========================================================================
        -- 5. GET TAX SUMMARY
        -- =========================================================================
        SELECT 
            SUM(ISNULL(IND_AMT, 0)) AS TotalTaxableAmount,
            SUM(ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_BASIC_CentralT, 0) / 100, 2)) AS TotalCgst,
            SUM(ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_EDU_CESS_State, 0) / 100, 2)) AS TotalSgst,
            SUM(ROUND(ISNULL(IND_AMT, 0) * ISNULL(E_H_EDU_Integrated, 0) / 100, 2)) AS TotalIgst,
            SUM(ROUND(
                (ISNULL(IND_AMT, 0) * ISNULL(E_BASIC_CentralT, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_EDU_CESS_State, 0) / 100) +
                (ISNULL(IND_AMT, 0) * ISNULL(E_H_EDU_Integrated, 0) / 100), 2
            )) AS TotalGst,
            (SELECT ISNULL(INM_G_AMT, 0) FROM INVOICE_MASTER WHERE INM_CODE = @InvoiceCode) AS TotalAmount,
            '' AS AmountInWords,  -- Will be calculated in C#
            MAX(ISNULL(INM.INM_TAX_TCS, 0)) AS TcsPercentage,
            MAX(ISNULL(INM.INM_TAX_TCS_AMT, 0)) AS TcsAmount
        FROM INVOICE_DETAIL
        INNER JOIN INVOICE_MASTER INM ON INM.INM_CODE = IND_INM_CODE
        WHERE IND_INM_CODE = @InvoiceCode
        AND INVOICE_DETAIL.ES_DELETE = 0;

        -- =========================================================================
        -- 6. GET E-INVOICE INFORMATION (if exists)
        -- =========================================================================
        SELECT 
            ISNULL(IRN, '') AS Irn,
            ISNULL(AckNo, '') AS AcknowledgementNumber,
            AckDate AS AcknowledgementDate,
            ISNULL(EwayBill, '') AS EwayBillNumber,
            NULL AS QrCodeImage,  -- QRCode column might be text or image, handle in C#
            ISNULL(EInvStatus, '') AS EInvoiceStatus
        FROM INVOICE_MASTER
        WHERE INM_CODE = @InvoiceCode
        AND ES_DELETE = 0;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

-- =============================================
-- Tax Invoice Print Data - FINAL CORRECT VERSION
-- ALL column names verified from actual database
-- Matches EXACT invoice format from taxinvoice_page-0001.jpg
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetTaxInvoicePrintData_V2]
    @InvoiceCode INT,
    @CompanyId INT
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Declare variables
    DECLARE @CustomerCode INT;
    
    -- Get customer code
    SELECT @CustomerCode = INM_P_CODE
    FROM INVOICE_MASTER
    WHERE INM_CODE = @InvoiceCode
    AND ISNULL(ES_DELETE, 0) = 0;
    
    -- ============================================
    -- Result Set 1: Company Information (Header)
    -- Simple format: Company name, full address, GSTIN
    -- ============================================
    SELECT 
        ISNULL(CM_NAME, '') AS CompanyName,
        -- Address is already complete in CM_ADDRESS1 for company 1
        ISNULL(CM_ADDRESS1, '') AS FullAddress,
        ISNULL(CM_GST_NO, '') AS GstinNo
    FROM COMPANY_MASTER
    WHERE CM_ID = @CompanyId 
    AND ISNULL(CM_DELETE_FLAG, 0) = 0;
    
    -- ============================================
    -- Result Set 2: Invoice Header (Left + Right columns)
    -- Left: Date, Serial No, GSTIN, E-Way Bill
    -- Right: Transport, Vehicle, PO No, Date/Time of Supply, Place
    -- ============================================
    SELECT 
        -- Left Column
        INM.INM_DATE AS DateOfInvoice,
        ISNULL(INM.INM_TNO, '') AS InvoiceSerialNo,  -- e.g., "SUN252605801"
        ISNULL(CM.CM_GST_NO, '') AS GstinNo,
        ISNULL(INM.EwayBill, '') AS EWayBillNo,
        
        -- Right Column
        ISNULL(INM.INM_TRANSPORT, '') AS TransporatationMode,  -- Note: keeping typo from actual invoice
        ISNULL(INM.INM_VEH_NO, '') AS VehicleNo,
        -- Get PO from first line item (PO is linked at line item level, not invoice header)
        ISNULL((SELECT TOP 1 CPO.CPOM_PONO 
                FROM INVOICE_DETAIL IND
                INNER JOIN CUSTPO_MASTER CPO ON CPO.CPOM_CODE = IND.IND_CPOM_CODE
                WHERE IND.IND_INM_CODE = INM.INM_CODE 
                AND ISNULL(IND.ES_DELETE, 0) = 0
                AND ISNULL(CPO.ES_DELETE, 0) = 0), '') AS PoNo,
        INM.INM_DATE AS DateAndTimeOfSupply,  -- Date with time
        ISNULL(CM_STATE.SM_NAME, 'Maharashtra') AS PlaceOfSupply
    FROM INVOICE_MASTER INM
    INNER JOIN COMPANY_MASTER CM ON CM.CM_CODE = INM.INM_CM_CODE AND CM.CM_ID = @CompanyId
    LEFT JOIN STATE_MASTER CM_STATE ON CM_STATE.SM_CODE = CM.CM_STATE AND ISNULL(CM_STATE.ES_DELETE, 0) = 0
    WHERE INM.INM_CODE = @InvoiceCode 
    AND ISNULL(INM.ES_DELETE, 0) = 0
    AND ISNULL(CM.CM_DELETE_FLAG, 0) = 0;
    
    -- ============================================
    -- Result Set 3: Recipient Details (Left side)
    -- "Details Of Recipient"
    -- Uses ReciptGSTIn from INVOICE_MASTER (not from PARTY_MASTER)
    -- State from PARTY_MASTER.P_STM_CODE joined with STATE_MASTER, with fallback to GSTIN first 2 digits
    -- ============================================
    SELECT 
        ISNULL(PM.P_NAME, '') AS Name,
        -- Build address: Area,City,Dist-City-PinCode
        ISNULL(PM.P_ADD1, '') + 
        CASE WHEN ISNULL(PM.P_CITY, '') <> '' THEN ',Dist-' + PM.P_CITY ELSE '' END +
        CASE WHEN ISNULL(PM.P_PIN_CODE, '') <> '' THEN '-' + PM.P_PIN_CODE ELSE '' END AS Address,
        -- State from PARTY_MASTER.P_STM_CODE joined with STATE_MASTER, with fallback to GSTIN first 2 digits
        ISNULL(COALESCE(SM_PSTM.SM_NAME, SM_GSTIN.SM_NAME), '') AS StateName,
        ISNULL(COALESCE(SM_PSTM.SM_STATE_CODE, SM_GSTIN.SM_STATE_CODE), '') AS StateCode,  -- e.g., "27"
        ISNULL(INM.ReciptGSTIn, '') AS GstinNo  -- From INVOICE_MASTER, not PARTY_MASTER
    FROM INVOICE_MASTER INM
    INNER JOIN PARTY_MASTER PM ON PM.P_CODE = INM.INM_P_CODE AND ISNULL(PM.ES_DELETE, 0) = 0
    -- Try to get state from P_STM_CODE first
    LEFT JOIN STATE_MASTER SM_PSTM ON SM_PSTM.SM_CODE = PM.P_STM_CODE AND ISNULL(SM_PSTM.ES_DELETE, 0) = 0
    -- Fallback: derive state from GSTIN first 2 digits if P_STM_CODE is NULL
    LEFT JOIN STATE_MASTER SM_GSTIN ON SM_PSTM.SM_CODE IS NULL 
        AND LEN(INM.ReciptGSTIn) >= 2 
        AND SM_GSTIN.SM_STATE_CODE = LEFT(INM.ReciptGSTIn, 2)
        AND ISNULL(SM_GSTIN.ES_DELETE, 0) = 0
    WHERE INM.INM_CODE = @InvoiceCode
    AND ISNULL(INM.ES_DELETE, 0) = 0;
    
    -- ============================================
    -- Result Set 4: Delivery Details (Right side)
    -- "Details Of Delivery" - Usually same as recipient
    -- Uses ReciptGSTIn from INVOICE_MASTER (not from PARTY_MASTER)
    -- State from PARTY_MASTER.P_STM_CODE joined with STATE_MASTER, with fallback to GSTIN first 2 digits
    -- ============================================
    SELECT 
        ISNULL(PM.P_NAME, '') AS Name,
        ISNULL(PM.P_ADD1, '') + 
        CASE WHEN ISNULL(PM.P_CITY, '') <> '' THEN ',Dist-' + PM.P_CITY ELSE '' END +
        CASE WHEN ISNULL(PM.P_PIN_CODE, '') <> '' THEN '-' + PM.P_PIN_CODE ELSE '' END AS Address,
        -- State from PARTY_MASTER.P_STM_CODE joined with STATE_MASTER, with fallback to GSTIN first 2 digits
        ISNULL(COALESCE(SM_PSTM.SM_NAME, SM_GSTIN.SM_NAME), '') AS StateName,
        ISNULL(COALESCE(SM_PSTM.SM_STATE_CODE, SM_GSTIN.SM_STATE_CODE), '') AS StateCode,
        ISNULL(INM.ReciptGSTIn, '') AS GstinNo  -- From INVOICE_MASTER, not PARTY_MASTER
    FROM INVOICE_MASTER INM
    INNER JOIN PARTY_MASTER PM ON PM.P_CODE = INM.INM_P_CODE AND ISNULL(PM.ES_DELETE, 0) = 0
    -- Try to get state from P_STM_CODE first
    LEFT JOIN STATE_MASTER SM_PSTM ON SM_PSTM.SM_CODE = PM.P_STM_CODE AND ISNULL(SM_PSTM.ES_DELETE, 0) = 0
    -- Fallback: derive state from GSTIN first 2 digits if P_STM_CODE is NULL
    LEFT JOIN STATE_MASTER SM_GSTIN ON SM_PSTM.SM_CODE IS NULL 
        AND LEN(INM.ReciptGSTIn) >= 2 
        AND SM_GSTIN.SM_STATE_CODE = LEFT(INM.ReciptGSTIn, 2)
        AND ISNULL(SM_GSTIN.ES_DELETE, 0) = 0
    WHERE INM.INM_CODE = @InvoiceCode
    AND ISNULL(INM.ES_DELETE, 0) = 0;
    
    -- ============================================
    -- Result Set 5: Line Items
    -- Columns: Sr. No | Description Of Goods Or Services | HSN/SAC | UOM | Qty | Rate/Unit | Taxable Value
    -- ============================================
    SELECT 
        ROW_NUMBER() OVER (ORDER BY ISNULL(IND.IND_SR_NO, 999999), IND.IND_I_CODE) AS SrNo,
        -- Description format: "26728738 - BRUSH PLATE ASSEMBLY" (using I_CODENO, not I_CODE which is PK)
        ISNULL(IM.I_CODENO, '') + ' - ' + ISNULL(IM.I_NAME, '') AS DescriptionOfGoodsOrServices,
        ISNULL(IND.IND_HSN_CODE, '') AS HsnSac,
        ISNULL(UM.I_UOM_NAME, 'NOS') AS Uom,
        ISNULL(IND.IND_INQTY, 0) AS Qty,
        ISNULL(IND.IND_RATE, 0) AS RatePerUnit,
        ISNULL(IND.IND_AMT, 0) AS TaxableValue,
        -- Tax percentages (for tax calculation)
        ISNULL(IND.E_BASIC_CentralT, 0) AS CgstPercentage,
        ISNULL(IND.E_EDU_CESS_State, 0) AS SgstPercentage,
        ISNULL(IND.E_H_EDU_Integrated, 0) AS IgstPercentage
    FROM INVOICE_DETAIL IND
    INNER JOIN ITEM_MASTER IM ON IM.I_CODE = IND.IND_I_CODE
    LEFT JOIN ITEM_UNIT_MASTER UM ON UM.I_UOM_CODE = IND.IND_UOM_CODE
    WHERE IND.IND_INM_CODE = @InvoiceCode
    AND ISNULL(IND.ES_DELETE, 0) = 0
    ORDER BY ISNULL(IND.IND_SR_NO, 999999), IND.IND_I_CODE;
    
    -- ============================================
    -- Result Set 6: Totals and Tax Summary
    -- Format: Less/Add sections, then Taxable Value, then Taxes, then Grand Total
    -- ============================================
    SELECT TOP 1
        -- Less/Add sections
        MAX(ISNULL(INM.INM_DISC_AMT, 0)) AS Discount,
        MAX(ISNULL(INM.INM_PACK_AMT, 0)) AS PackingAndForwardingCharges,
        MAX(ISNULL(INM.INM_FREIGHT, 0)) + MAX(ISNULL(INM.INM_INSURANCE, 0)) AS FrieghtAndInsurance,  -- Note: keeping typo "Frieght" from actual invoice
        MAX(ISNULL(INM.INM_OTHER_AMT, 0)) AS OtherCharges,
        
        -- Taxable Value (after Less/Add)
        MAX(ISNULL(INM.INM_TAXABLE_AMT, 0)) AS TaxableValue,
        
        -- Tax percentages and amounts
        -- IMPORTANT: Labels are "Central Tax" and "State/Union Territory Tax", NOT CGST/SGST
        -- Use tax percentages from INVOICE_MASTER if available, otherwise from INVOICE_DETAIL
        -- Since we're using GROUP BY, we need to use MAX() for INVOICE_MASTER columns (only one row per invoice)
        CASE WHEN MAX(INM.INM_BEXCISE) IS NOT NULL AND MAX(INM.INM_BEXCISE) > 0 
             THEN MAX(INM.INM_BEXCISE) 
             ELSE MAX(ISNULL(IND.E_BASIC_CentralT, 0)) 
        END AS CentralTaxPercentage,
        CASE WHEN MAX(INM.INM_BE_AMT) IS NOT NULL AND MAX(INM.INM_BE_AMT) > 0 
             THEN MAX(INM.INM_BE_AMT) 
             ELSE SUM(ROUND(ISNULL(IND.IND_AMT, 0) * ISNULL(IND.E_BASIC_CentralT, 0) / 100, 2)) 
        END AS CentralTaxAmount,
        
        CASE WHEN MAX(INM.INM_EDUC_CESS) IS NOT NULL AND MAX(INM.INM_EDUC_CESS) > 0 
             THEN MAX(INM.INM_EDUC_CESS) 
             ELSE MAX(ISNULL(IND.E_EDU_CESS_State, 0)) 
        END AS StateUnionTerritoryTaxPercentage,
        CASE WHEN MAX(INM.INM_EDUC_AMT) IS NOT NULL AND MAX(INM.INM_EDUC_AMT) > 0 
             THEN MAX(INM.INM_EDUC_AMT) 
             ELSE SUM(ROUND(ISNULL(IND.IND_AMT, 0) * ISNULL(IND.E_EDU_CESS_State, 0) / 100, 2)) 
        END AS StateUnionTerritoryTaxAmount,
        
        CASE WHEN MAX(INM.INM_H_EDUC_CESS) IS NOT NULL AND MAX(INM.INM_H_EDUC_CESS) > 0 
             THEN MAX(INM.INM_H_EDUC_CESS) 
             ELSE MAX(ISNULL(IND.E_H_EDU_Integrated, 0)) 
        END AS IntegratedTaxPercentage,
        CASE WHEN MAX(INM.INM_H_EDUC_AMT) IS NOT NULL AND MAX(INM.INM_H_EDUC_AMT) > 0 
             THEN MAX(INM.INM_H_EDUC_AMT) 
             ELSE SUM(ROUND(ISNULL(IND.IND_AMT, 0) * ISNULL(IND.E_H_EDU_Integrated, 0) / 100, 2)) 
        END AS IntegratedTaxAmount,
        
        -- Grand Total
        MAX(ISNULL(INM.INM_G_AMT, 0)) AS GrandTotal,
        '' AS AmountInWords  -- Will be calculated in C# using NumberToWordsConverter
    FROM INVOICE_MASTER INM
    INNER JOIN INVOICE_DETAIL IND ON IND.IND_INM_CODE = INM.INM_CODE AND ISNULL(IND.ES_DELETE, 0) = 0
    WHERE INM.INM_CODE = @InvoiceCode
    AND ISNULL(INM.ES_DELETE, 0) = 0
    GROUP BY INM.INM_CODE;
    
    -- ============================================
    -- Result Set 7: E-Invoice Information
    -- Bottom left section with QR code
    -- ============================================
    SELECT 
        ISNULL(IRN, '') AS Irn,
        ISNULL(AckNo, '') AS AckNo,
        AckDate AS AckDate,
        NULL AS QrCodeImage  -- QR code will be generated from IRN in C# using QRCoder
    FROM INVOICE_MASTER
    WHERE INM_CODE = @InvoiceCode
    AND ISNULL(ES_DELETE, 0) = 0;
    
    -- ============================================
    -- Result Set 8: Terms and Conditions
    -- Fixed list for now (can be made configurable later)
    -- ============================================
    SELECT '1) Goods Once Sold will not be taken back.' AS TermCondition
    UNION ALL
    SELECT '2)Unless informed at time of receipt, no shortages claim will be accepted.'
    UNION ALL
    SELECT '3) Interest Rate @24% P.A. applicable for Overdue Payment.';
    
END
GO

-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-10-24
-- Description: Gets basic user information (username and company ID)
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_GetUserBasicInfo]
    @UserId INT
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        SELECT 
            UM_USERNAME AS Username,
            UM_CM_ID AS CompanyId
        FROM USER_MASTER
        WHERE UM_CODE = @UserId;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetUserByCode]
    @UserCode INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        um.UM_CODE                                       AS UserCode,
        um.UM_USERNAME                                   AS Username,
        um.UM_NAME                                       AS DisplayName,
        um.UM_EMAIL                                      AS UserEmail,
        ISNULL(um.UM_IS_ADMIN, 0)                        AS IsAdmin,
        um.UM_CM_ID                                      AS CompanyId,
        cm.CM_CODE                                       AS FinancialYearCode,
        cm.CM_NAME                                       AS CompanyName,
        cm.CM_EMAILID                                    AS CompanyEmail,
        CONVERT(VARCHAR(10), cm.CM_OPENING_DATE, 103)    AS OpeningDate,
        CONVERT(VARCHAR(10), cm.CM_CLOSING_DATE, 103)    AS ClosingDate
    FROM  USER_MASTER  um
    INNER JOIN COMPANY_MASTER cm ON um.UM_CM_ID = cm.CM_ID
    WHERE um.UM_CODE      = @UserCode
      AND um.IS_ACTIVE    = 1
      AND um.ES_DELETE    = 0
      AND cm.CM_ACTIVE_IND = 1;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetUserForAuth]
    @Username          NVARCHAR(50),
    @CompanyId         INT,
    @FinancialYearCode INT       -- maps to COMPANY_MASTER.CM_CODE
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        um.UM_CODE                                       AS UserCode,
        um.UM_USERNAME                                   AS Username,
        um.UM_NAME                                       AS DisplayName,
        um.UM_EMAIL                                      AS UserEmail,
        um.UM_PASSWORD                                   AS PasswordHash,  -- legacy cipher or bcrypt
        ISNULL(um.UM_IS_ADMIN, 0)                        AS IsAdmin,
        um.UM_CM_ID                                      AS CompanyId,
        cm.CM_CODE                                       AS FinancialYearCode,
        cm.CM_NAME                                       AS CompanyName,
        cm.CM_EMAILID                                    AS CompanyEmail,
        CONVERT(VARCHAR(10), cm.CM_OPENING_DATE, 103)    AS OpeningDate,
        CONVERT(VARCHAR(10), cm.CM_CLOSING_DATE, 103)    AS ClosingDate,
        ISNULL(cm.CM_ADDRESS1, '')                       AS CompanyAddress
    FROM  USER_MASTER  um
    INNER JOIN COMPANY_MASTER cm ON um.UM_CM_ID = cm.CM_ID
    WHERE um.UM_USERNAME    = @Username
      AND um.UM_CM_ID       = @CompanyId
      AND cm.CM_CODE        = @FinancialYearCode
      AND um.IS_ACTIVE      = 1
      AND um.ES_DELETE      = 0
      AND cm.CM_ACTIVE_IND  = 1;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_GetUserPermissions]
    @UserCode INT
AS
BEGIN
    SET NOCOUNT ON;

    -- Bitmask positions: 0=View 1=Add 2=Edit 3=Delete 4=Print 5=Approve 6=Export
    SELECT
        UR_SM_CODE  AS ModuleCode,
        UR_RIGHTS   AS RightsBitmask
    FROM  USER_RIGHT
    WHERE UR_UM_CODE   = @UserCode
      AND UR_IS_DELETE = 0
    ORDER BY UR_SM_CODE;
END
GO

