CREATE OR ALTER PROCEDURE [dbo].[ERP_IsSoTypeFixedRecord]
    @SO_T_CODE INT
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Fixed records are -2147483648 and -2147483647 (legacy business rule)
    IF @SO_T_CODE IN (-2147483648, -2147483647)
    BEGIN
        SELECT CAST(1 AS BIT) AS IsFixed;
    END
    ELSE
    BEGIN
        SELECT CAST(0 AS BIT) AS IsFixed;
    END
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_IsSoTypeShortNameUnique]
    @SO_T_SHORT_NAME VARCHAR(50),
    @SO_T_COMP_ID INT,
    @ExcludeId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT COUNT(*) AS DuplicateCount
    FROM SO_TYPE_MASTER
    WHERE LOWER(SO_T_SHORT_NAME) = LOWER(@SO_T_SHORT_NAME)
        AND SO_T_COMP_ID = @SO_T_COMP_ID
        AND ES_DELETE = 0
        AND (@ExcludeId IS NULL OR SO_T_CODE != @ExcludeId);
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_IsTypeCodeUnique]
    @CTM_TYPE_CODE VARCHAR(50),
    @ExcludeId INT = NULL,
    @CTM_CM_COMP_ID INT,
    @IsUnique BIT OUTPUT
AS
BEGIN
    SET NOCOUNT OFF;

    DECLARE @Count INT;

    SELECT @Count = COUNT(*)
    FROM CUSTOMER_TYPE_MASTER
    WHERE LOWER(CTM_TYPE_CODE) = LOWER(@CTM_TYPE_CODE)
        AND CTM_CM_COMP_ID = @CTM_CM_COMP_ID
        AND ES_DELETE = 0
        AND (@ExcludeId IS NULL OR CTM_CODE <> @ExcludeId);

    IF @Count = 0
        SET @IsUnique = 1;
    ELSE
        SET @IsUnique = 0;
END;
GO

