-- =============================================
-- Author:      AI Assistant
-- Create date: 2025-01-24
-- Description: Updates an existing Tax Invoice (all fields)
-- =============================================
CREATE OR ALTER PROCEDURE [dbo].[ERP_UpdateTaxInvoice]
    @InvoiceCode INT,
    -- (Same parameters as Create, except @InvoiceNumber which doesn't change)
    @CompanyCode INT,
    @InvoiceDate DATETIME,
    @InvoiceType TINYINT = NULL,
    @Type VARCHAR(20) = NULL,
    @PaymentMethodCode INT = NULL,
    @CustomerCode INT,
    @CustomerPoCode INT = NULL,
    @DateFrom DATETIME = NULL,
    @DateTo DATETIME = NULL,
    @IsSupplementary BIT = NULL,
