    @FlightNumber VARCHAR(50) = NULL,
    @ManufacturingDate DATETIME = NULL,
    @ExpiryDate DATETIME = NULL,
    @CurrencyRate FLOAT = NULL,
    @AuthorizedSignatory VARCHAR(200) = NULL,
    @AreaFormNumber VARCHAR(50) = NULL,
    @FormDate DATETIME = NULL,
    @Shipment VARCHAR(100) = NULL,
    @CenvatAccountNumber VARCHAR(50) = NULL,
    @BondNumber VARCHAR(50) = NULL,
    @BondDate DATETIME = NULL,
    @Ut1FileNumber VARCHAR(50) = NULL,
    @FileNumber VARCHAR(50) = NULL,
    @ExportFlag BIT = NULL,
    @ValidityDate DATETIME = NULL,
    @ExaminationBoxes VARCHAR(100) = NULL,
    @TermsOfDelivery VARCHAR(200) = NULL,
    @TermsOfPayment VARCHAR(200) = NULL,
    @VoyageNumber VARCHAR(50) = NULL,
    @PlaceOfReceipt VARCHAR(200) = NULL,
    @MarksAndNumbers VARCHAR(500) = NULL,
    @NumberOfPackages VARCHAR(50) = NULL,
    @UnNumber VARCHAR(50) = NULL,
    @HazardClass VARCHAR(50) = NULL,
    @HsCodeNumber VARCHAR(50) = NULL,
    @ContainerNumber VARCHAR(50) = NULL,
    @SealNumber VARCHAR(50) = NULL,
    @OtsNumber VARCHAR(50) = NULL,
    @CountryOfOrigin INT = NULL,
    @CountryOfDestination INT = NULL,
    @TransportBy VARCHAR(100) = NULL,
    @AreaRemarks VARCHAR(500) = NULL,
    @CarrierName VARCHAR(200) = NULL,
    @CarrierBookingNumber VARCHAR(50) = NULL,
    @ShipName VARCHAR(200) = NULL,
    @TechnicalName VARCHAR(200) = NULL,
    @OuterPackaging VARCHAR(200) = NULL,
    @InnerPackaging VARCHAR(200) = NULL,
    @SubsidiaryClass VARCHAR(50) = NULL,
    @UnPackingGroup VARCHAR(50) = NULL,
    @UnPackingCode VARCHAR(50) = NULL,
    @EmsNumber VARCHAR(50) = NULL,
    @FlashPoint VARCHAR(50) = NULL,
    @MarinePollutant BIT = NULL,
    @ShipperDeclaration VARCHAR(500) = NULL,
    @IecNumber VARCHAR(50) = NULL,
    @IecDate DATETIME = NULL,
    @CentralExciseRegistration VARCHAR(100) = NULL,
    @DateOfExamination DATETIME = NULL,
    @SuperintendentExciseName VARCHAR(200) = NULL,
    @InspectorExciseName VARCHAR(200) = NULL,
    @CustomsSealNumber VARCHAR(50) = NULL,
    @PermitENumber VARCHAR(50) = NULL,
    @NonCargoNumberOfPackages VARCHAR(50) = NULL,
    @ShippingBillNumber VARCHAR(50) = NULL,
    @AccessibleAmount FLOAT = NULL,
    @TaxableAmount FLOAT = NULL,
    @RoundingAmount FLOAT = NULL,
    @AdvanceDuty FLOAT = NULL,
    @OctriAmount FLOAT = NULL,
    @IssueTime VARCHAR(20) = NULL,
    @RemovalTime VARCHAR(20) = NULL,
    @LcNumber VARCHAR(50) = NULL,
    @LcDate DATETIME = NULL,
    @TransportOwner VARCHAR(200) = NULL,
    @TransportAddress VARCHAR(500) = NULL,
    @TNumber VARCHAR(50) = NULL,
    @TrayCode INT = NULL,
    @TrayQuantity FLOAT = NULL,
    @Address VARCHAR(500) = NULL,
    @StateCode INT = NULL,
    @HsnCode VARCHAR(50) = NULL,
    @ElectronicReferenceNumber VARCHAR(100) = NULL,
    @TermsAndConditions VARCHAR(MAX) = NULL,
    @AuthorizedName VARCHAR(200) = NULL,
    @AddressSelected INT = NULL
AS
BEGIN
    SET NOCOUNT OFF;

    BEGIN TRY
        -- Reverse old stock entries (delete all stock ledger entries for this invoice)
        DELETE FROM STOCK_LEDGER
        WHERE STL_DOC_NO = @InvoiceCode 
        AND STL_DOC_TYPE = 'TAXINV';
        
        -- Update INVOICE_MASTER
        UPDATE INVOICE_MASTER
        SET 
            INM_CM_CODE = @CompanyCode,
            INM_DATE = @InvoiceDate,
            INM_INVOICE_TYPE = @InvoiceType,
            INM_TYPE = @Type,
            INM_PMM_CODE = @PaymentMethodCode,
            INM_P_CODE = @CustomerCode,
            INM_CPOM_CODE = @CustomerPoCode,
            INM_DF_DATE = @DateFrom,
            INM_DT_DATE = @DateTo,
            INM_SUPPLEMENTORY = @IsSupplementary,
            INM_PROCESS = @Process,
            INM_NET_AMT = @NetAmount,
            INM_S_TAX = @ServiceTaxPercentage,
            INM_S_TAX_AMT = @ServiceTaxAmount,
            INM_BEXCISE = @BasicExcisePercentage,
            INM_BE_AMT = @BasicExciseAmount,
            INM_EDUC_CESS = @EducationCessPercentage,
            INM_EDUC_AMT = @EducationCessAmount,
            INM_H_EDUC_CESS = @HigherEducationCessPercentage,
            INM_H_EDUC_AMT = @HigherEducationCessAmount,
            INM_DISC = @DiscountPercentage,
            INM_DISC_AMT = @DiscountAmount,
            INM_PACK_AMT = @PackingAmount,
            INM_PACK_DCES = @PackingDescription,
            INM_T_CODE = @TaxCode,
            INM_T_AMT = @TaxAmount,
            INM_G_AMT = @GrossAmount,
            INM_G_AMORT_AMT = @GrossAmortizationAmount,
            INM_TAX_TCS = @TcsPercentage,
            INM_TAX_TCS_AMT = @TcsAmount,
            INM_FREIGHT = @FreightCharges,
            INM_VEH_NO = @VehicleNumber,
            INM_TRANSPORT = @TransportName,
            INM_ISSUE_DATE = @IssueDate,
            INM_REMOVAL_DATE = @RemovalDate,
            INM_STO_LOC = @StorageLocation,
            INM_REMARK = @Remarks,
            INM_C_DAYS = @CreditDays,
            INM_ASN_NO = @AsnNumber,
            INM_NATURE_PRO = @NatureOfProduct,
            INM_PREPARE_BY = @PreparedBy,
            INM_REWORK_FLAG = @ReworkFlag,
            INM_TRIFF_NO = @TariffNumber,
            INM_TRIFF_NAME = @TariffName,
            INM_TRANS_AMT = @TransportAmount,
            INM_COURIER_AMT = @CourierAmount,
            INM_SER_PER = @ServicePercentage,
            INM_SER_AMT = @ServiceAmount,
            INM_SER_EDUC_CESS = @ServiceEducationCessPercentage,
            INM_SER_EDUC_CESS_AMT = @ServiceEducationCessAmount,
            INM_SER_H_EDUC_CESS = @ServiceHigherEducationCessPercentage,
            INM_SER_H_EDUC_CESS_AMT = @ServiceHigherEducationCessAmount,
            INM_DEL_ADD = @DeliveryAddress,
            INM_P_CODE_ALT = @AlternateCustomerCode,
            INM_OTHER_AMT = @OtherAmount,
            INM_LR_NO = @LrNumber,
            INM_LR_DATE = @LrDate,
            INM_BUYER_NAME = @BuyerName,
            INM_BUYTER_ADD = @BuyerAddress,
            INM_INSURANCE = @InsuranceAmount,
            INM_FINAL_DEST = @FinalDestination,
            INM_PRE_CARRIAGE = @PreCarriage,
            INM_PORT_OF_LOAD = @PortOfLoading,
            INM_PORT_OF_DISCH = @PortOfDischarge,
            INM_PLACE_OF_DEL = @PlaceOfDelivery,
            INM_CURR_CODE = @CurrencyCode,
            INM_CLEARANCE = @Clearance,
            INM_FLIGHT_NO = @FlightNumber,
            INM_MFG_DATE = @ManufacturingDate,
            INM_EXP_DATE = @ExpiryDate,
            INM_CURR_RATE = @CurrencyRate,
            INM_AUTHO_SIGN = @AuthorizedSignatory,
            INM_AREA_FORM_NO = @AreaFormNumber,
            INM_FORM_DATE = @FormDate,
            INM_SHIPMENT = @Shipment,
            INM_CENVAT_AC_NO = @CenvatAccountNumber,
            INM_BOND_NO = @BondNumber,
            INM_BOND_DATE = @BondDate,
            INM_UT1_FILE_NO = @Ut1FileNumber,
            INM_FILE_NO = @FileNumber,
            INM_EXPORT_FLAG = @ExportFlag,
            INM_VALID_DATE = @ValidityDate,
            INM_EXA_BOXES = @ExaminationBoxes,
            INM_TOD = @TermsOfDelivery,
            INM_TOP = @TermsOfPayment,
            INM_VOY_NO = @VoyageNumber,
            INM_PLACE_REC = @PlaceOfReceipt,
            INM_M_NO = @MarksAndNumbers,
            INM_NOS_PACK = @NumberOfPackages,
            INM_UN_NO = @UnNumber,
            INM_HAZ = @HazardClass,
            INM_HS_CODENO = @HsCodeNumber,
            INM_CONTA_NO = @ContainerNumber,
            INM_SEAL_NO = @SealNumber,
            INM_OTS_NO = @OtsNumber,
            INM_CONTRY_ORIGIN = @CountryOfOrigin,
            INM_COUNTRY_DEST = @CountryOfDestination,
            INM_TRANSPORT_BY = @TransportBy,
            INM_ARE_REMARK = @AreaRemarks,
            INM_CARRIER_NAME = @CarrierName,
            INM_CARRIER_BOOK_NO = @CarrierBookingNumber,
            INM_SHIP_NAME = @ShipName,
            INM_TECH_NAME = @TechnicalName,
            INM_OUT_PAKGS = @OuterPackaging,
            INM_INR_PAKG = @InnerPackaging,
            INM_SUB_CLASS = @SubsidiaryClass,
            INM_UN_PAK_GRP = @UnPackingGroup,
            INM_UN_PAK_CODE = @UnPackingCode,
            INM_EMS_NO = @EmsNumber,
            INM_FLASH_POINT = @FlashPoint,
            INM_MARINE_POLLT = @MarinePollutant,
            INM_SHIP_DECLAR = @ShipperDeclaration,
            INM_IEC_NO = @IecNumber,
            INM_IEC_DATE = @IecDate,
            INM_CEN_EXC_REG = @CentralExciseRegistration,
            INM_DATE_OF_EXAM = @DateOfExamination,
            INM_SUP_C_EXC_NAME = @SuperintendentExciseName,
            INM_INSP_C_EXC_NAME = @InspectorExciseName,
            INM_CUST_SEAL_NO = @CustomsSealNumber,
            INM_PER_E_NO = @PermitENumber,
            INM_NONCARGO_NOPAKG = @NonCargoNumberOfPackages,
            INM_SHIPP_BILL_NO = @ShippingBillNumber,
            INM_ACCESSIBLE_AMT = @AccessibleAmount,
            INM_TAXABLE_AMT = @TaxableAmount,
            INM_ROUNDING_AMT = @RoundingAmount,
            INM_ADV_DUTY = @AdvanceDuty,
            INM_OCTRI_AMT = @OctriAmount,
            INM_ISSU_TIME = @IssueTime,
            INM_REMOVEL_TIME = @RemovalTime,
            INM_LC_NO = @LcNumber,
            INM_LC_DATE = @LcDate,
            INM_TRANSPORT_OWNER = @TransportOwner,
            INM_TRANSPORT_ADDRESS = @TransportAddress,
            INM_TNO = @TNumber,
            INM_TRAY_CODE = @TrayCode,
            INM_TRAY_QTY = @TrayQuantity,
            INM_ADDRESS = @Address,
            INM_STATE = @StateCode,
            INM_HSN_CODE = @HsnCode,
            INM_ELECTRREFNUM = @ElectronicReferenceNumber,
            INM_TERMSNCONDITIONS = @TermsAndConditions,
            INM_AUTHORIZEDNAME = @AuthorizedName,
            INM_ADDRESS_SELECTED = @AddressSelected
        WHERE INM_CODE = @InvoiceCode AND INM_CM_CODE = @CompanyCode;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();
        
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE [dbo].[ERP_ValidateAndRotateRefreshToken]
    @TokenHash     NVARCHAR(500),
    @NewTokenHash  NVARCHAR(500)   -- hash of the incoming replacement token
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRANSACTION;

    BEGIN TRY
        DECLARE @UserCode  INT;
        DECLARE @TokenCode INT;

        -- Find a valid (non-revoked, non-expired) token
        SELECT
            @UserCode  = URT_UM_CODE,
            @TokenCode = URT_CODE
        FROM  USER_REFRESH_TOKEN
        WHERE URT_TOKEN_HASH = @TokenHash
          AND URT_IS_REVOKED = 0
          AND URT_EXPIRES_AT > GETUTCDATE();

        IF @UserCode IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT NULL AS UserCode;
            RETURN;
        END

        -- Mark old token as rotated
        UPDATE USER_REFRESH_TOKEN
        SET    URT_IS_REVOKED  = 1,
               URT_REPLACED_BY = @NewTokenHash
        WHERE  URT_CODE = @TokenCode;

        COMMIT TRANSACTION;

        SELECT @UserCode AS UserCode;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE GetInvoiceDetails
    @INM_CM_CODE INT,
    @INM_CODE NVARCHAR(50),
    @INM_TYPE NVARCHAR(10)
AS
BEGIN
    -- Optional: Set the format of dates
    SET DATEFORMAT dmy;
    
    SELECT DISTINCT
        dbo.ITEM_MASTER.I_CODE,
        dbo.PARTY_MASTER.P_CODE,
        dbo.EXCISE_TARIFF_MASTER.E_TARIFF_NO,
        dbo.PARTY_MASTER.P_NAME,
        dbo.PARTY_MASTER.P_ADD1,
        dbo.PARTY_MASTER.P_VEND_CODE,
        dbo.PARTY_MASTER.P_CST,
        dbo.PARTY_MASTER.P_VAT,
        dbo.PARTY_MASTER.P_ECC_NO,
        dbo.INVOICE_MASTER.INM_TNO,
        dbo.INVOICE_MASTER.INM_NO,
        CONVERT(VARCHAR, dbo.INVOICE_MASTER.INM_DATE, 103) AS INM_DATE,
        dbo.INVOICE_MASTER.INM_TRANSPORT,
        dbo.INVOICE_MASTER.INM_VEH_NO,
        dbo.INVOICE_MASTER.INM_LR_NO,
        CONVERT(VARCHAR, dbo.INVOICE_MASTER.INM_LR_DATE, 103) AS INM_LR_DATE,
        dbo.ITEM_MASTER.I_NAME,
        dbo.ITEM_MASTER.I_CODENO AS CPOD_CUST_I_CODE,
        dbo.INVOICE_DETAIL.IND_PACK_DESC AS CPOD_CUST_I_NAME,
        dbo.CUSTPO_MASTER.CPOM_PONO,
        '' AS ST_TAX_NAME,
        CONVERT(VARCHAR, dbo.CUSTPO_MASTER.CPOM_PO_DATE, 103) AS CPOM_DATE,
        dbo.INVOICE_DETAIL.IND_SUBHEADING,
        dbo.INVOICE_DETAIL.IND_BACHNO,
        dbo.INVOICE_DETAIL.IND_NO_PACK,
        CAST(ISNULL(dbo.INVOICE_DETAIL.IND_PAK_QTY, 0) AS NUMERIC(20, 3)) AS IND_PAK_QTY,
        CAST(ISNULL(dbo.INVOICE_DETAIL.IND_INQTY, 0) AS NUMERIC(20, 3)) AS IND_INQTY,
        CAST(ISNULL(dbo.INVOICE_DETAIL.IND_RATE, 0) AS NUMERIC(20, 2)) AS IND_RATE,
        CAST(ISNULL(dbo.INVOICE_DETAIL.IND_AMT, 0) AS NUMERIC(20, 2)) AS IND_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_NET_AMT, 0) AS NUMERIC(20, 2)) AS INM_NET_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_DISC, 0) AS NUMERIC(20, 2)) AS INM_DISC,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_DISC_AMT, 0) AS NUMERIC(20, 2)) AS INM_DISC_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_PACK_AMT, 0) AS NUMERIC(20, 2)) AS INM_PACK_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_ACCESSIBLE_AMT, 0) AS NUMERIC(20, 2)) AS INM_ACCESSIBLE_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_BEXCISE, 0) AS NUMERIC(20, 2)) AS INM_BEXCISE,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_BE_AMT, 0) AS NUMERIC(20, 2)) AS INM_BE_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_EDUC_CESS, 0) AS NUMERIC(20, 2)) AS INM_EDUC_CESS,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_EDUC_AMT, 0) AS NUMERIC(20, 2)) AS INM_EDUC_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_H_EDUC_CESS, 0) AS NUMERIC(20, 2)) AS INM_H_EDUC_CESS,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_H_EDUC_AMT, 0) AS NUMERIC(20, 2)) AS INM_H_EDUC_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_TAXABLE_AMT, 0) AS NUMERIC(20, 2)) AS INM_TAXABLE_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_S_TAX, 0) AS NUMERIC(20, 2)) AS INM_S_TAX,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_S_TAX_AMT, 0) AS NUMERIC(20, 2)) AS INM_S_TAX_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_OTHER_AMT, 0) AS NUMERIC(20, 2)) AS INM_OTHER_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_FREIGHT, 0) AS NUMERIC(20, 2)) AS INM_FREIGHT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_INSURANCE, 0) AS NUMERIC(20, 2)) AS INM_INSURANCE,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_TRANS_AMT, 0) AS NUMERIC(20, 2)) AS INM_TRANS_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_OCTRI_AMT, 0) AS NUMERIC(20, 2)) AS INM_OCTRI_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_ROUNDING_AMT, 0) AS NUMERIC(20, 2)) AS INM_ROUNDING_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_G_AMT, 0) AS NUMERIC(20, 2)) AS INM_G_AMT,
        CAST(ISNULL(dbo.INVOICE_MASTER.INM_TAX_TCS_AMT, 0) AS NUMERIC(20, 2)) AS INM_TAX_TCS_AMT,
        CONVERT(VARCHAR, dbo.INVOICE_MASTER.INM_ISSUE_DATE, 103) AS INM_ISSUE_DATE,
        dbo.INVOICE_MASTER.INM_REMOVAL_DATE,
        dbo.INVOICE_MASTER.INM_ISSU_TIME,
        dbo.INVOICE_MASTER.INM_REMOVEL_TIME,
        dbo.EXCISE_TARIFF_MASTER.E_COMMODITY,
        dbo.ITEM_UNIT_MASTER.I_UOM_NAME,
        dbo.INVOICE_MASTER.INM_TAX_TCS,
        ISNULL(dbo.INVOICE_DETAIL.IND_AMORTAMT, 0) AS IND_AMORTAMT,
        ISNULL(dbo.INVOICE_DETAIL.IND_AMORTRATE, 0) AS IND_AMORTRATE,
        ISNULL(dbo.INVOICE_DETAIL.IND_HSN_CODE, '') AS HSN_NO,
        ISNULL(dbo.INVOICE_MASTER.INM_HSN_CODE, '') AS EWAYBILL_NO,
        dbo.INVOICE_MASTER.INM_ELECTRREFNUM,
        dbo.INVOICE_MASTER.INM_ADDRESS,
        dbo.INVOICE_MASTER.INM_STATE,
        ISNULL(dbo.PARTY_MASTER.P_LBT_NO, '') AS P_GST_NO,
        ISNULL(dbo.INVOICE_DETAIL.IND_EX_AMT, 0) AS IND_EX_AMT,
        ISNULL(dbo.INVOICE_DETAIL.IND_E_CESS_AMT, 0) AS IND_E_CESS_AMT,
        ISNULL(dbo.INVOICE_DETAIL.IND_SH_CESS_AMT, 0) AS IND_SH_CESS_AMT,
        dbo.INVOICE_MASTER.INM_CODE,
        dbo.STATE_MASTER.SM_NAME,
        ISNULL(dbo.STATE_MASTER.SM_STATE_CODE, '') AS SM_STATE_CODE,
        STATE_MASTER1.SM_NAME AS SM_NAME_CUST,
        ISNULL(STATE_MASTER1.SM_STATE_CODE, '') AS SM_STATE_CODE_CUST,
        dbo.INVOICE_MASTER.AckNo,
        dbo.INVOICE_MASTER.AckDate,
        dbo.INVOICE_MASTER.InvValue,
        dbo.INVOICE_MASTER.ReciptGSTIn,
        dbo.INVOICE_MASTER.EInvStatus,
        dbo.INVOICE_MASTER.IRN,
        ISNULL(dbo.INVOICE_MASTER.QRCode, 0) AS QRCodeEinvPrint,
        ISNULL(dbo.INVOICE_MASTER.EwayBill, 0) AS EwayBill
    FROM 
        dbo.EXCISE_TARIFF_MASTER
        INNER JOIN dbo.ITEM_MASTER
            ON dbo.EXCISE_TARIFF_MASTER.E_CODE = dbo.ITEM_MASTER.I_E_CODE
        INNER JOIN dbo.INVOICE_DETAIL
            ON dbo.ITEM_MASTER.I_CODE = dbo.INVOICE_DETAIL.IND_I_CODE
        INNER JOIN dbo.INVOICE_MASTER
            ON dbo.INVOICE_DETAIL.IND_INM_CODE = dbo.INVOICE_MASTER.INM_CODE
        INNER JOIN dbo.PARTY_MASTER
            ON dbo.INVOICE_MASTER.INM_P_CODE = dbo.PARTY_MASTER.P_CODE
        INNER JOIN dbo.CUSTPO_MASTER
            ON dbo.INVOICE_MASTER.INM_P_CODE = dbo.CUSTPO_MASTER.CPOM_P_CODE
            AND dbo.INVOICE_DETAIL.IND_CPOM_CODE = dbo.CUSTPO_MASTER.CPOM_CODE
        INNER JOIN dbo.CUSTPO_DETAIL
            ON dbo.CUSTPO_MASTER.CPOM_CODE = dbo.CUSTPO_DETAIL.CPOD_CPOM_CODE
            AND dbo.INVOICE_DETAIL.IND_I_CODE = dbo.CUSTPO_DETAIL.CPOD_I_CODE
        INNER JOIN dbo.ITEM_UNIT_MASTER
            ON dbo.ITEM_MASTER.I_UOM_CODE = dbo.ITEM_UNIT_MASTER.I_UOM_CODE
        INNER JOIN dbo.STATE_MASTER
            ON dbo.INVOICE_MASTER.INM_STATE = dbo.STATE_MASTER.SM_CODE
        INNER JOIN dbo.STATE_MASTER AS STATE_MASTER1
            ON dbo.PARTY_MASTER.P_SM_CODE = STATE_MASTER1.SM_CODE
    WHERE 
        dbo.INVOICE_MASTER.INM_CM_CODE = @INM_CM_CODE
        AND dbo.INVOICE_MASTER.INM_CODE = @INM_CODE
        AND dbo.INVOICE_MASTER.INM_TYPE = @INM_TYPE
        AND dbo.STATE_MASTER.ES_DELETE = 0
        AND STATE_MASTER1.ES_DELETE = 0;
END;
GO

CREATE OR ALTER PROCEDURE [dbo].[prGetOPCLBalance] --'04-Feb-2015','07-Feb-2015'

(@fromdate datetime,
	@todate datetime)	
as
	
BEGIN
 DECLARE @ItemCode int = 0
 DECLARE @PartyCode int = 0
 DECLARE @Date Datetime = null
 DECLARE @OPBal float = 0
 DECLARE @CLBal float = 0
   DECLARE tmpAllow CURSOR
   FOR select CL_P_CODE,CL_I_CODE,CL_DOC_DATE from CHALLAN_STOCK_LEDGER_REPORT 
   OPEN tmpAllow  
   FETCH NEXT FROM tmpAllow  
   INTO @PartyCode,@ItemCode,@Date
   WHILE @@FETCH_STATUS = 0  
   BEGIN
		Set @OPBal = (SELECT isnull(SUM(CL_CQTY),0) FROM CHALLAN_STOCK_LEDGER WHERE CL_I_CODE = @ItemCode AND CL_P_CODE =@PartyCode AND CL_DOC_DATE<@fromdate)
		Set @CLBal = (SELECT isnull(SUM(CL_CQTY),0) FROM CHALLAN_STOCK_LEDGER WHERE CL_I_CODE = @ItemCode AND CL_P_CODE =@PartyCode AND CL_DOC_DATE<=@todate)
		
		Update CHALLAN_STOCK_LEDGER_REPORT Set OP_BAL = @OPBal,CL_BAL = @CLBal
		Where CL_P_CODE =@PartyCode and CL_I_CODE = @ItemCode and CL_DOC_DATE= @Date
       FETCH NEXT FROM tmpAllow  
    INTO @PartyCode,@ItemCode,@Date
   END  
   CLOSE tmpAllow;  
   DEALLOCATE tmpAllow;
   select * from CHALLAN_STOCK_LEDGER_REPORT 
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_ActivateUser] @UserId INT, @IsActive BIT AS BEGIN SET NOCOUNT OFF; BEGIN TRY UPDATE [USER_MASTER] SET [IS_ACTIVE] = @IsActive WHERE [UM_CODE] = @UserId AND [ES_DELETE] = 0 END TRY BEGIN CATCH DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE() DECLARE @ErrorSeverity INT = ERROR_SEVERITY() DECLARE @ErrorState INT = ERROR_STATE() RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState) END CATCH END
GO

