CREATE OR ALTER PROCEDURE [dbo].[SP_CleanupOldLogs]
    @DaysToKeep INT = 30,
    @DeletedCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @CutoffDate DATETIME = DATEADD(DAY, -@DaysToKeep, GETUTCDATE());
    
    DELETE FROM Logs
    WHERE TimeStamp < @CutoffDate;
    
    SET @DeletedCount = @@ROWCOUNT;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_CM_DELETE] --'-2147483647','IWM_CODE',1,'ES_DELETE','INWARD_MASTER'

@PK_CODE int,
@PK_Field varchar(30),
@ES_DELETE int,
@DELETE VARCHAR(10),
@TABLE_NAME varchar(50)


AS
BEGIN
	--select @fname,@code from @TbName where @cond
	exec('Update ' +''  + @TABLE_NAME +' set  '+ @DELETE +' = ' + @ES_DELETE + ' where ' +' '+ @PK_Field +' = ' +@PK_CODE +'')
END
GO

