CREATE OR ALTER PROCEDURE [dbo].[SP_GetAuditTrail]
    @TableName NVARCHAR(100),
    @RecordId INT = NULL,
    @PageNumber INT = 1,
    @PageSize INT = 50,
    @TotalCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    
    -- Get total count
    SELECT @TotalCount = COUNT(*)
    FROM [dbo].[AUDIT_TRAIL]
    WHERE [TABLE_NAME] = @TableName
    AND (@RecordId IS NULL OR [RECORD_ID] = @RecordId);
    
    -- Get paginated results with proper column aliases
    SELECT
        [AUDIT_ID] AS AuditId,
        [TABLE_NAME] AS TableName,
        [RECORD_ID] AS RecordId,
        [ACTION_TYPE] AS ActionType,
        [OLD_VALUES] AS OldValues,
        [NEW_VALUES] AS NewValues,
        [CREATED_DATE] AS CreatedDate,
        [CREATED_BY] AS CreatedBy,
        [MODIFIED_DATE] AS ModifiedDate,
        [MODIFIED_BY] AS ModifiedBy,
        [IP_ADDRESS] AS IpAddress,
        [USER_AGENT] AS UserAgent,
        [SESSION_ID] AS SessionId
    FROM [dbo].[AUDIT_TRAIL]
    WHERE [TABLE_NAME] = @TableName
    AND (@RecordId IS NULL OR [RECORD_ID] = @RecordId)
    ORDER BY [CREATED_DATE] DESC
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_GetItemCategoryMasterById]
    @I_CAT_CODE INT
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT 
        I_CAT_CODE AS CategoryId,
        I_CAT_NAME AS CategoryName,
        I_CAT_CM_COMP_ID AS CompanyId,
        I_CAT_SHORTCLOSE AS IsAutoShortClose,
        CASE WHEN ES_DELETE = 0 THEN 1 ELSE 0 END AS IsActive
    FROM ITEM_CATEGORY_MASTER
    WHERE I_CAT_CODE = @I_CAT_CODE;
END
