CREATE OR ALTER PROCEDURE [dbo].[SP_GetItemCategoryMasters]
    @PageNumber INT = 1,
    @PageSize INT = 15,
    @SortBy NVARCHAR(50) = 'I_CAT_NAME',
    @SortDirection NVARCHAR(4) = 'ASC',
    @SearchTerm NVARCHAR(200) = NULL,
    @CompanyId INT = NULL,
    @IsActive BIT = NULL,
    @IsAutoShortClose BIT = NULL,
    @TotalCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    
    -- Validate and set defaults
    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize < 1 SET @PageSize = 15;
    IF @PageSize > 100 SET @PageSize = 100;
    
    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;
    
    -- Get total count
    SELECT @TotalCount = COUNT(*)
    FROM ITEM_CATEGORY_MASTER
    WHERE 
        (@CompanyId IS NULL OR I_CAT_CM_COMP_ID = @CompanyId)
        AND (@IsActive IS NULL OR (CASE WHEN ES_DELETE = 0 THEN 1 ELSE 0 END) = @IsActive)
        AND (@IsAutoShortClose IS NULL OR I_CAT_SHORTCLOSE = @IsAutoShortClose)
        AND (@SearchTerm IS NULL OR I_CAT_NAME LIKE '%' + @SearchTerm + '%');
    
    -- Get paginated results with dynamic sorting
    DECLARE @SQL NVARCHAR(MAX);
    SET @SQL = '
    SELECT 
        I_CAT_CODE AS CategoryId,
        I_CAT_NAME AS CategoryName,
        I_CAT_CM_COMP_ID AS CompanyId,
        I_CAT_SHORTCLOSE AS IsAutoShortClose,
        CASE WHEN ES_DELETE = 0 THEN 1 ELSE 0 END AS IsActive
    FROM ITEM_CATEGORY_MASTER
    WHERE 
        (@CompanyId IS NULL OR I_CAT_CM_COMP_ID = @CompanyId)
        AND (@IsActive IS NULL OR (CASE WHEN ES_DELETE = 0 THEN 1 ELSE 0 END) = @IsActive)
        AND (@IsAutoShortClose IS NULL OR I_CAT_SHORTCLOSE = @IsAutoShortClose)
        AND (@SearchTerm IS NULL OR I_CAT_NAME LIKE ''%'' + @SearchTerm + ''%'')
    ORDER BY ' + QUOTENAME(@SortBy) + ' ' + @SortDirection + '
    OFFSET @Offset ROWS
    FETCH NEXT @PageSize ROWS ONLY';
    
    EXEC sp_executesql @SQL,
        N'@CompanyId INT, @IsActive BIT, @IsAutoShortClose BIT, @SearchTerm NVARCHAR(200), @Offset INT, @PageSize INT',
        @CompanyId, @IsActive, @IsAutoShortClose, @SearchTerm, @Offset, @PageSize;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_GetLogs]
    @PageNumber INT = 1,
    @PageSize INT = 50,
    @Level NVARCHAR(50) = NULL,
    @SearchTerm NVARCHAR(500) = NULL,
    @StartDate DATETIME = NULL,
    @EndDate DATETIME = NULL,
    @TotalCount INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    -- Ensure valid page number and size
    IF @PageNumber < 1 SET @PageNumber = 1;
    IF @PageSize < 1 SET @PageSize = 50;
    IF @PageSize > 100 SET @PageSize = 100;

    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    -- Get total count
    SELECT @TotalCount = COUNT(*)
    FROM Logs
    WHERE 
        (@Level IS NULL OR Level = @Level)
        AND (@SearchTerm IS NULL OR Message LIKE '%' + @SearchTerm + '%')
        AND (@StartDate IS NULL OR TimeStamp >= @StartDate)
        AND (@EndDate IS NULL OR TimeStamp <= @EndDate);

    -- Get paginated logs
    SELECT 
        Id,
        TimeStamp,
        ISNULL(Level, 'Information') as Level,
        ISNULL(Message, 'No message') as Message,
        ISNULL(Exception, '') as Exception,
        ISNULL(Properties, '') as Properties,
        ISNULL(UserId, '') as UserId,
        ISNULL(RequestId, '') as RequestId,
        ISNULL(ActionName, '') as ActionName
    FROM Logs
    WHERE 
        (@Level IS NULL OR Level = @Level)
        AND (@SearchTerm IS NULL OR Message LIKE '%' + @SearchTerm + '%')
        AND (@StartDate IS NULL OR TimeStamp >= @StartDate)
        AND (@EndDate IS NULL OR TimeStamp <= @EndDate)
    ORDER BY TimeStamp DESC
    OFFSET @Offset ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_GetLogStatistics]
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT 
        ISNULL(Level, 'Information') AS Level,
        COUNT(*) AS Count,
        MIN(TimeStamp) AS OldestLog,
        MAX(TimeStamp) AS NewestLog
    FROM Logs
    GROUP BY Level;
END
GO

