CREATE OR ALTER PROCEDURE [dbo].[SP_IsItemCategoryNameUnique]
    @I_CAT_NAME NVARCHAR(50),
    @I_CAT_CM_COMP_ID INT,
    @ExcludeCategoryId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    SELECT COUNT(*) AS Count
    FROM ITEM_CATEGORY_MASTER
    WHERE I_CAT_NAME = @I_CAT_NAME
      AND I_CAT_CM_COMP_ID = @I_CAT_CM_COMP_ID
      AND (@ExcludeCategoryId IS NULL OR I_CAT_CODE != @ExcludeCategoryId)
      AND ES_DELETE = 0;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[SP_IsUnitNameUnique] --'TEST_UNIT_e7d55356',1,null
    @UnitName VARCHAR(100),
    @CompanyId INT,
    @ExcludeId INT = NULL
AS
BEGIN
    SET NOCOUNT OFF;
    
    SELECT count(*)
    FROM ITEM_UNIT_MASTER
    WHERE I_UOM_NAME = @UnitName
    AND I_UOM_CM_COMP_ID = @CompanyId
    AND ES_DELETE = 0
    AND (@ExcludeId IS NULL OR I_UOM_CODE != @ExcludeId);
END
GO

