CREATE OR ALTER PROCEDURE testSales as
BEGIN
SELECT  DISTINCT(I_CODE),I_CODENO,INM_NET_AMT,I_TARGET_WEIGHT AS INTFINISHWEIGHT,I_UWEIGHT AS INTCASTWEIGHT,I_DENSITY AS BDFINISHWEIGH,I_TARGET_WEIGHT*IND_INQTY AS INTCASTWT,I_TARGET_WEIGHT*IND_INQTY AS INTFINWT ,I_DENSITY*IND_INQTY AS BDWT,P_CODE,P_NAME,P_ADD1,P_CST,P_VAT,P_ECC_NO,INM_NO,INM_DATE,INM_TRANSPORT,I_NAME,CPOD_CUST_I_CODE,CPOM_PONO,CPOM_DATE,IND_SUBHEADING,IND_BACHNO,CONVERT(VARCHAR(11),CPOM_DATE,113) as CPOM_DATE,IND_SUBHEADING,IND_BACHNO,IND_NO_PACK,cast(isnull(IND_PAK_QTY,0) as numeric(20,3)) as IND_PAK_QTY,  CASE when INM_IS_SUPPLIMENT =1 then 0 else  cast(isnull(IND_INQTY,0) as numeric(20,3)) END as IND_INQTY,cast(isnull(IND_RATE,0) as numeric(20,2)) as IND_RATE,cast(isnull(IND_AMT,0) as numeric(20,2)) as IND_AMT,cast(isnull(INM_NET_AMT,0) as numeric(20,2)) as INM_NET_AMT,cast(isnull(INM_DISC,0) as numeric(20,2)) as INM_DISC,cast(isnull(INM_DISC_AMT,0) as numeric(20,2)) as INM_DISC_AMT,cast(isnull(INM_PACK_AMT,0) as numeric(20,2)) as INM_PACK_AMT,cast(isnull(INM_ACCESSIBLE_AMT,0) as numeric(20,2)) as INM_ACCESSIBLE_AMT,cast(isnull(INM_BEXCISE,0) as numeric(20,2)) as INM_BEXCISE,cast(isnull(INM_BE_AMT,0) as numeric(20,2)) as INM_BE_AMT,cast(isnull(INM_EDUC_CESS,0) as numeric(20,2)) as INM_EDUC_CESS,cast(isnull(INM_EDUC_AMT,0) as numeric(20,2)) as INM_EDUC_AMT,cast(isnull(INM_H_EDUC_CESS,0) as numeric(20,2)) as INM_H_EDUC_CESS,cast(isnull(INM_H_EDUC_AMT,0) as numeric(20,2)) as INM_H_EDUC_AMT,cast(isnull(INM_TAXABLE_AMT,0) as numeric(20,2)) as INM_TAXABLE_AMT,cast(isnull(INM_S_TAX,0) as numeric(20,2)) as INM_S_TAX,cast(isnull(INM_S_TAX_AMT,0) as numeric(20,2)) as INM_S_TAX_AMT,cast(isnull(INM_OTHER_AMT,0) as numeric(20,2)) as INM_OTHER_AMT,cast(isnull(INM_FREIGHT,0) as numeric(20,2)) as INM_FREIGHT,cast(isnull(INM_INSURANCE,0) as numeric(20,2)) as INM_INSURANCE,cast(isnull(INM_TRANS_AMT,0) as numeric(20,2)) as INM_TRANS_AMT,cast(isnull(INM_OCTRI_AMT,0) as numeric(20,2)) as INM_OCTRI_AMT,cast(isnull(INM_ROUNDING_AMT,0) as numeric(20,2)) as INM_ROUNDING_AMT,cast(isnull(INM_G_AMT,0) as numeric(20,2)) as INM_G_AMT,cast(isnull(INM_TAX_TCS_AMT,0) as numeric(20,2)) as INM_TAX_TCS_AMT ,I_UOM_NAME,CASE WHEN INM_TYPE='TAXINV' then 'Sales'  WHEN INM_TYPE='OutJWINM' then 'Labour Charge' END AS INM_TYPE,INM_TNO FROM INVOICE_MASTER,INVOICE_DETAIL,CUSTPO_MASTER,CUSTPO_DETAIL,ITEM_MASTER,PARTY_MASTER,ITEM_UNIT_MASTER WHERE INM_CODE=IND_INM_CODE AND CPOM_CODE=CPOD_CPOM_CODE AND IND_CPOM_CODE =CPOM_CODE AND IND_I_CODE=CPOD_I_CODE AND I_CODE=IND_I_CODE AND ITEM_UNIT_MASTER.I_UOM_CODE=ITEM_MASTER.I_UOM_CODE AND INVOICE_MASTER.ES_DELETE=0 AND INM_P_CODE=P_CODE   AND INM_DATE BETWEEN '01-Dec-2024' AND '25-Dec-2024' 



GROUP BY INM_LR_DATE,I_CODENO,I_CODE,INM_NO,P_CODE,P_NAME,P_ADD1,P_VEND_CODE,P_CST,P_VAT,P_ECC_NO,INM_DATE,INM_TRANSPORT,INM_LR_NO,I_NAME,CPOD_CUST_I_CODE,CPOD_CUST_I_NAME,CPOM_PONO,CPOM_DATE,IND_SUBHEADING,IND_BACHNO,IND_NO_PACK,IND_PAK_QTY,IND_INQTY,IND_RATE,INM_VEH_NO,IND_AMT,INM_NET_AMT,INM_DISC,INM_DISC_AMT,INM_PACK_AMT,INM_ACCESSIBLE_AMT,INM_BEXCISE,INM_BE_AMT,INM_EDUC_CESS,INM_EDUC_AMT,INM_H_EDUC_CESS,INM_H_EDUC_AMT,INM_TAXABLE_AMT,INM_S_TAX,INM_S_TAX_AMT,INM_OTHER_AMT,INM_FREIGHT,INM_INSURANCE,INM_TRANS_AMT,INM_OCTRI_AMT,INM_ROUNDING_AMT,INM_G_AMT,INM_TAX_TCS_AMT,INM_IS_SUPPLIMENT,INM_TNO,I_UOM_NAME,INM_TYPE,I_TARGET_WEIGHT,I_UWEIGHT,I_DENSITY

END
GO

CREATE OR ALTER PROCEDURE [dbo].[timepass3] AS
BEGIN
declare @CE_CODE int=0,
@dyear varchar(max)='',
@QE_CM_COMP_ID int=0,
@PROCM_CODE int =0,
@SPOM_PROJECT varchar(max)=''
DECLARE tmpEmployee CURSOR
        FOR select distinct PROCM_CODE,SPOM_PROJECT from SUPP_PO_MASTER,PROJECT_CODE_MASTER where PROCM_NAME=SPOM_PROJECT
        OPEN tmpEmployee
        FETCH NEXT FROM tmpEmployee
        INTO @PROCM_CODE,@SPOM_PROJECT
            WHILE @@FETCH_STATUS = 0
            BEGIN
            update SUPP_PO_MASTER set SPOM_PROJECT=@PROCM_CODE where SPOM_PROJECT=@SPOM_PROJECT
            fetch next from tmpEmployee
            into  @PROCM_CODE,@SPOM_PROJECT
            END        
            CLOSE tmpEmployee;  
            DEALLOCATE tmpEmployee;
END

--exec('timepass3')
GO

CREATE OR ALTER PROCEDURE [dbo].[usp_GetDropdownData]
    @Table NVARCHAR(100),
    @IdColumn NVARCHAR(50),
    @DisplayColumn NVARCHAR(50),
    @WhereClause NVARCHAR(500) = NULL,
    @OrderBy NVARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @Sql NVARCHAR(MAX);
    
    -- Build the SQL query
    SET @Sql = 'SELECT ' + @IdColumn + ' AS Id, ' + @DisplayColumn + ' AS DisplayName FROM ' + @Table;
    
    -- Add WHERE clause if provided
    IF @WhereClause IS NOT NULL AND @WhereClause <> ''
    BEGIN
        SET @Sql = @Sql + ' WHERE ' + @WhereClause;
    END;
    
    -- Add ORDER BY clause if provided
    IF @OrderBy IS NOT NULL AND @OrderBy <> ''
    BEGIN
        SET @Sql = @Sql + ' ORDER BY ' + @OrderBy;
    END;
    
    -- Execute the dynamic SQL
    EXEC sp_executesql @Sql;
END
GO

CREATE OR ALTER PROCEDURE [dbo].[usp_GetDropdownDataPaged]
    @Table NVARCHAR(100),
    @IdColumn NVARCHAR(50),
    @DisplayColumn NVARCHAR(50),
    @WhereClause NVARCHAR(1000) = NULL,
    @OrderBy NVARCHAR(100) = NULL,
    @SearchText NVARCHAR(250) = NULL,
    @Skip INT = 0,
    @Take INT = 20
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Sql NVARCHAR(MAX) = '';
    DECLARE @Where NVARCHAR(MAX) = '';
    DECLARE @Order NVARCHAR(MAX) = '';
    DECLARE @SearchFilter NVARCHAR(252);

    -- Build WHERE clause
    IF @WhereClause IS NOT NULL AND LTRIM(RTRIM(@WhereClause)) <> ''
        SET @Where = ' WHERE ' + @WhereClause;

    -- Add search filter
    IF @SearchText IS NOT NULL AND LTRIM(RTRIM(@SearchText)) <> ''
    BEGIN
        SET @SearchFilter = '%' + @SearchText + '%';
        IF LEN(@Where) > 0
            SET @Where = @Where + ' AND ([' + @DisplayColumn + '] LIKE @SearchFilter OR CONVERT(VARCHAR(50),[' + @IdColumn + ']) LIKE @SearchFilter)';
        ELSE
            SET @Where = ' WHERE ([' + @DisplayColumn + '] LIKE @SearchFilter OR CONVERT(VARCHAR(50),[' + @IdColumn + ']) LIKE @SearchFilter)';
    END
    ELSE
        SET @SearchFilter = NULL;

    -- Order by clause with paging
    IF @OrderBy IS NOT NULL AND LEN(@OrderBy) > 0
        SET @Order = ' ORDER BY ' + @OrderBy + ' OFFSET @Skip ROWS FETCH NEXT @Take ROWS ONLY';
    ELSE
        SET @Order = ' ORDER BY [' + @DisplayColumn + '] ASC OFFSET @Skip ROWS FETCH NEXT @Take ROWS ONLY';

    -- Final SQL for paged data and count
    SET @Sql = 'SELECT [' + @IdColumn + '] AS Id, [' + @DisplayColumn + '] AS DisplayName FROM [' + @Table + ']'
        + @Where + @Order + ';'
        + ' SELECT COUNT(1) AS TotalCount FROM [' + @Table + ']' + @Where + ';';

    EXEC sp_executesql
        @Sql,
        N'@Skip INT, @Take INT, @SearchFilter NVARCHAR(252)',
        @Skip = @Skip,
        @Take = @Take,
        @SearchFilter = @SearchFilter;
END
GO

